INSERT INTO `aulas` (`id_aula`, `id_modulo`, `titulo_aula`, `conteudo_aula`, `ordem_aula`, `id_admin_criador`, `data_criacao`, `id_admin_editor`, `data_atualizacao`) VALUES
	(1, 1, 'O que é Pensamento Computacional?', 'Introdução aos 4 pilares básicos para resolver problemas complexos de forma estruturada.', 1, 1, '2026-08-26 10:35:10', NULL, NULL),
	(2, 1, 'Pilar 1: Decomposição', 'Aprenda a quebrar um grande problema em partes menores e mais fáceis de gerenciar.', 2, 1, '2026-08-26 10:35:10', NULL, NULL),
	(3, 1, 'Pilar 2: Reconhecimento de Padrões', 'Identificação de semelhanças ou características compartilhadas entre problemas.', 3, 1, '2026-08-26 10:35:10', NULL, NULL),
	(4, 1, 'Pilar 3: Abstração', 'Filtragem de detalhes irrelevantes, focando apenas no que é crucial para a solução.', 4, 1, '2026-08-26 10:35:10', NULL, NULL),
	(5, 1, 'Pilar 4: Algoritmos', 'Criação de um conjunto de instruções passo a passo para resolver um desafio.', 5, 1, '2026-08-26 10:35:10', NULL, NULL),
	(6, 1, 'O Conceito de Instruções Sequenciais', 'Como computadores seguem ordens de cima para baixo de maneira estrita.', 6, 1, '2026-08-26 10:35:10', NULL, NULL),
	(7, 1, 'Lógica no Cotidiano', 'Mapeando atividades do dia a dia (como escovar os dentes) na forma de processos lógicos.', 7, 1, '2026-08-26 10:35:10', NULL, NULL),
	(8, 1, 'Entradas e Saídas (Inputs e Outputs)', 'Entendendo como dados entram em um sistema e como os resultados são entregues.', 8, 1, '2026-08-26 10:35:10', NULL, NULL),
	(9, 1, 'Introdução às Tomadas de Decisão', 'O conceito intuitivo de caminhos alternativos dependendo de condições (Se/Então).', 9, 1, '2026-08-26 10:35:10', NULL, NULL),
	(10, 1, 'Revisão do Fluxo Lógico', 'Consolidação dos conceitos aprendidos e preparação para modelar fluxos estruturados.', 10, 1, '2026-08-26 10:35:10', NULL, NULL),
	(11, 2, 'A Transição do Raciocínio para a Linguagem Estruturada', 'Nesta aula, você aprenderá por que precisamos padronizar nossos pensamentos em uma estrutura de Pseudocódigo antes de partir para a sintaxe rígida das linguagens de programação.', 1, 1, '2026-09-12 15:23:50', NULL, NULL),
	(12, 2, 'Organizando o Fluxo Lógico (Início, Meio e Fim)', 'Todo algoritmo precisa de um ponto de partida claro, uma sequência de instruções organizadas e um ponto de término. Nesta aula, entenderemos como delimitar o escopo de execução.', 2, 1, '2026-09-12 15:26:08', NULL, NULL),
	(13, 2, 'O Conceito de Memória e Variáveis no Mundo Real', 'Para processar dados, os computadores precisam guardar informações temporariamente. Nesta aula, entenderemos as variáveis como caixas etiquetadas na memória que guardam e atualizam valores.', 3, 1, '2026-09-12 15:32:22', NULL, NULL),
	(14, 2, 'Classificando os Dados (Tipos de Dados Simples)', 'Para que o computador saiba como processar o valor contido em uma variável, precisamos categorizar os dados em tipos fundamentais: Texto (Caractere), Números Inteiros, Números Decimais (Real) e Lógicos (Verdadeiro/Falso).', 4, 1, '2026-09-12 15:34:48', NULL, NULL),
	(15, 2, 'Formalizando Entrada e Saída em Pseudocódigo (Leia e Escreva)', 'Agora que entendemos a estrutura e as variáveis, vamos formalizar os comandos essenciais de interação em Portugol: Escreva para exibir mensagens na tela (Saída) e Leia para capturar os dados digitados (Entrada).', 5, 1, '2026-09-12 15:37:34', NULL, NULL),
	(16, 2, 'Operações Aritméticas e Expressões Simples', 'Nesta aula, avançamos no processamento de dados aprendendo a utilizar os operadores aritméticos (+, -, *, /) para realizar cálculos em pseudocódigo e armazenar os resultados em variáveis.', 6, 1, '2026-09-12 15:38:58', NULL, NULL),
	(17, 2, 'Introdução às Tomadas de Decisão (Estrutura Se-Entao)', 'Aprenda como permitir que seu algoritmo tome decisões e siga caminhos diferentes com base em condições lógicas utilizando a estrutura Se-Então.', 7, 1, '2026-09-12 15:41:22', NULL, NULL),
	(18, 2, 'Decisões Compostas (Estrutura Se-Entao-Senao)', 'Aprenda a tratar caminhos alternativos em seu algoritmo. Com a estrutura Se-Então-Senão, seu programa executa um bloco caso a condição seja verdadeira e outro bloco diferente caso seja falsa.', 8, 1, '2026-09-12 15:47:29', NULL, NULL),
	(19, 2, 'Condições Múltiplas e Operadores Lógicos (E, OU, NAO)', 'Aprenda a avaliar mais de uma condição ao mesmo tempo utilizando os operadores lógicos E, OU e NÃO para criar regras de decisão mais complexas em pseudocódigo.', 9, 1, '2026-09-12 15:49:10', NULL, NULL),
	(20, 2, 'Consolidação e Projeto Prático do Módulo 2', 'Integrando todos os conceitos aprendidos no Módulo 2: desde a estruturação de algoritmos, manipulação de variáveis, operadores aritméticos, entrada e saída até o uso de condicionais simples, compostas e com múltiplos operadores.', 10, 1, '2026-09-12 15:49:49', NULL, NULL),
	(21, 3, 'Introdução aos Laços de Repetição (Estrutura Enquanto)', 'Compreenda a necessidade de automatizar tarefas repetitivas. Nesta aula, exploraremos o laço Enquanto, testando a condição no início antes de executar o bloco de instruções.', 1, 1, '2026-09-24 19:41:52', NULL, NULL),
	(22, 3, 'Repetição com Teste no Final (Estrutura Faca-Enquanto / Repita-Ate)', 'Aprenda a utilizar laços de repetição onde a condição é validada ao final da execução. Essa estrutura garante que o bloco de código seja executado pelo menos uma vez antes do primeiro teste.', 2, 1, '2026-09-24 19:46:00', NULL, NULL),
	(23, 3, 'Repetição Determinada (Estrutura Para / Para-Ate)', 'Aprenda a utilizar o laço Para para executar repetições com número de iterações previamente conhecido. A estrutura controla automaticamente a inicialização, o teste e o incremento da variável contadora.', 3, 1, '2026-09-24 20:08:30', NULL, NULL),
	(24, 3, 'Aninhamento de Laços de Repetição', 'Aprenda a estruturar laços de repetição dentro de outros laços. Entenda como funciona a execução de laços internos e externos para resolver problemas multidimensionais e combinações de dados.', 4, 1, '2026-09-24 20:09:44', NULL, NULL),
	(25, 3, 'Introdução a Vetores (Arrays Unidimensionais)', 'Compreenda o conceito de variáveis compostas homogêneas. Aprenda a declarar, manipular e acessar coleções de dados do mesmo tipo em uma única estrutura sequencial utilizando índices.', 5, 1, '2026-09-24 20:09:44', NULL, NULL),
	(26, 3, 'Operações com Vetores (Busca, Maior/Menor e Acumuladores)', 'Aprenda a aplicar algoritmos clássicos sobre vetores. Descubra como percorrer uma estrutura unidimensional para localizar valores específicos, identificar elementos extremos (maior e menor valor) e calcular médias ou acumulados.', 6, 1, '2026-09-24 20:10:36', NULL, NULL),
	(27, 3, 'Introdução a Matrizes (Arrays Bidimensionais)', 'Compreenda o funcionamento de matrizes como tabelas compostas de linhas e colunas. Aprenda a declarar, indexar com dois subsobrescritos [linha, coluna] e manipular dados bidimensionais.', 7, 1, '2026-09-24 20:10:37', NULL, NULL),
	(28, 3, 'Operações Avançadas com Matrizes (Diagonais e Somatórios)', 'Aprofunde seus conhecimentos em matrizes quadradas. Aprenda a identificar e manipular a diagonal principal e a diagonal secundária, além de realizar somatórios específicos por linha e por coluna.', 8, 1, '2026-09-24 20:12:19', NULL, NULL),
	(29, 3, 'Modularização (Procedimentos e Funções)', 'Aprenda a dividir programas complexos em blocos menores e reutilizáveis. Compreenda a diferença entre Procedimentos (sub-rotinas sem retorno) e Funções (sub-rotinas que retornam um valor).', 9, 1, '2026-09-24 20:12:19', NULL, NULL),
	(30, 3, 'Consolidação e Projeto Integrador do Módulo 3', 'Aplicações práticas e integradas de laços de repetição (Enquanto, Para, Faca-Enquanto), vetores, matrizes e modularização. Encerramento do Módulo 3 consolidando o raciocínio estruturado completo.', 10, 1, '2026-09-24 20:12:20', NULL, NULL),
	(31, 4, 'Algoritmos de Ordenação I (Bubble Sort)', 'Aprenda o funcionamento do algoritmo Bubble Sort (Ordenação por Bolha). Entenda como trocas sucessivas de elementos adjacentes organizam um vetor em ordem crescente ou decrescente.', 1, 1, '2026-09-24 20:48:59', NULL, NULL),
	(32, 4, 'Algoritmos de Ordenação II (Selection Sort)', 'Aprenda o funcionamento do Selection Sort (Ordenação por Seleção). Descubra como encontrar iterativamente o menor elemento da sub-lista não ordenada e trocá-lo para a posição correta.', 2, 1, '2026-09-24 20:48:59', NULL, NULL),
	(33, 4, 'Buscas Avançadas (Busca Binária vs. Busca Sequencial)', 'Compreenda o funcionamento da Busca Binária. Aprenda como a estratégia de "divisão e conquista" exige um vetor previamente ordenado para encontrar elementos de forma rápida em grandes conjuntos de dados.', 3, 1, '2026-09-24 20:48:59', NULL, NULL),
	(34, 4, 'Estruturas de Dados Heterogêneas (Registros / Structs)', 'Aprenda a agrupar variáveis de tipos diferentes sob um único nome utilizando Registros (Structs). Entenda como modelar entidades do mundo real como Aluno, Produto e Cliente.', 4, 1, '2026-09-24 20:48:59', NULL, NULL),
	(35, 4, 'Vetores de Registros (Arrays de Structs)', 'Aprenda a combinar Vetores com Registros para criar tabelas complexas de dados em memória. Crie cadastros completos com busca, listagem e ordenação.', 5, 1, '2026-09-24 20:49:00', NULL, NULL),
	(36, 4, 'Introdução à Recursividade', 'Entenda o conceito de funções recursivas. Aprenda como uma função pode chamar a si mesma para resolver problemas complexos através de Caso Base e Caso Recursivo.', 6, 1, '2026-09-24 20:49:00', NULL, NULL),
	(37, 4, 'Manipulação de Arquivos e Persistência de Dados', 'Aprenda a salvar e ler dados em arquivos de texto (TXT/DAT). Entenda o conceito de persistência de dados para evitar que as informações do sistema sejam perdidas ao fechar o programa.', 7, 1, '2026-09-24 20:49:00', NULL, NULL),
	(38, 4, 'Tratamento de Erros e Validação Robusta de Dados', 'Aprenda a construir programas tolerantes a falhas. Implemente validação de entradas, tratamento de exceções e prevenção de travamentos causados por dados inválidos.', 8, 1, '2026-09-24 20:49:00', NULL, NULL),
	(39, 4, 'Boas Práticas, Clean Code e Depuração (Debugging)', 'Aprenda a aplicar técnicas de Clean Code (Código Limpo), padrões de nomenclatura, indentação e estratégias de depuração de código usando Teste de Mesa e PONTOS DE PARADA (Breakpoints).', 9, 1, '2026-09-24 20:49:00', NULL, NULL),
	(40, 4, 'Projeto Final Integrador e Próximos Passos na Programação', 'Construção do Projeto Final do Módulo 4: Sistema de Gestão Completo utilizando Vetor de Registros, Ordenação, Busca Binária, Arquivos e Modularização. Transição para Linguagens de Programação Comerciais.', 10, 1, '2026-09-24 20:49:00', NULL, NULL),
	(41, 5, 'Estrutura Básica em C++ e Biblioteca iostream', 'Aprenda a estrutura fundamental de um programa em C++. Entenda a inclusão de cabeçalhos com #include <iostream>, o namespace std, o ponto de entrada int main() e o comando de saída cout.', 1, 1, '2026-09-28 10:32:15', NULL, NULL),
	(42, 5, 'Saída de Dados e Variáveis em C++ (Tipos Primitivos e cout)', 'Aprenda a declarar variáveis e utilizar os tipos de dados fundamentais em C++ (int, float, double, char, bool, string), além de dominar a exibição de dados e formatação com cout e endl.', 2, 1, '2026-09-28 10:37:00', NULL, NULL),
	(43, 5, 'Entrada de Dados em C++ (Comando cin)', 'Aprenda a realizar a leitura de dados digitados pelo usuário em C++ utilizando o comando cin e o operador de extração >>, fazendo a transição direta do comando leia que você aprendeu em Portugol.', 3, 1, '2026-09-28 10:39:33', NULL, NULL),
	(44, 5, 'Operadores Aritméticos e Expressões em C++', 'Aprenda a realizar operações matemáticas em C++ utilizando os operadores aritméticos de soma (+), subtração (-), multiplicação (*), divisão (/) e resto da divisão (%), aplicando a mesma lógica aprendida em Portugol.', 4, 1, '2026-09-28 10:41:25', NULL, NULL),
	(45, 5, 'Operadores Relacionais e Lógicos em C++', 'Aprenda a utilizar os operadores relacionais (==, !=, >, <, >=, <=) e lógicos (&&, ||, !) em C++, fazendo a correspondência direta com os operadores relacionais e lógicos (e, ou, nao) aprendidos em Portugol.', 5, 1, '2026-09-28 10:43:07', NULL, NULL),
	(46, 5, 'Estruturas Condicionais Simples e Compostas (if e else)', 'Aprenda a implementar desvios condicionais simples e compostos em C++ utilizando as instruções if e else, fazendo a transição direta das estruturas se e senao aprendidas em Portugol.', 6, 1, '2026-09-28 10:44:07', NULL, NULL),
	(47, 5, 'Estruturas Condicionais Aninhadas e Múltipla Escolha (else if e switch)', 'Aprenda a implementar estruturas condicionais encadeadas com else if e seleção múltipla com switch em C++, fazendo a transição direta das instruções senao se e escolha caso aprendidas em Portugol.', 7, 1, '2026-09-28 10:45:22', NULL, NULL),
	(48, 5, 'Estruturas de Repetição (Laço while)', 'Aprenda a implementar laços de repetição em C++ utilizando a instrução while, fazendo a correspondência direta com a estrutura enquanto aprendida em Portugol para repetição de código com teste no início.', 8, 1, '2026-09-28 10:45:44', NULL, NULL),
	(49, 5, 'Estruturas de Repetição (Laço for)', 'Aprenda a implementar laços de repetição com número determinado de iterações em C++ utilizando a instrução for, fazendo a correspondência direta com a estrutura para aprendida em Portugol.', 9, 1, '2026-09-28 10:46:57', NULL, NULL),
	(50, 5, 'Revisão Geral e Consolidação de Sintaxe em C++', 'Consolide todos os conhecimentos adquiridos no Módulo 5. Revise a sintaxe básica de C++, tipos de dados, entrada e saída com iostream, operadores, estruturas condicionais (if/else e switch) e laços de repetição (while, for e do-while).', 10, 1, '2026-09-28 10:47:37', NULL, NULL),
	(51, 6, 'Vetores Unidimensionais em C++ (Declaração e Acesso)', 'Aprenda a declarar e manipular vetores (arrays unidimensionais) em C++, compreendendo a indexação com início em zero e a equivalência direta com os vetores do Portugol.', 1, 1, '2026-09-28 11:05:19', NULL, NULL),
	(52, 6, 'Operações e Algoritmos com Vetores', 'Aprenda a aplicar algoritmos clássicos em vetores em C++, como cálculo de soma, média, busca pelo maior/menor valor, contagem condicional e cópia de vetores.', 2, 1, '2026-09-28 11:14:52', NULL, NULL),
	(53, 6, 'Matrizes em C++ (Arrays Bidimensionais)', 'Aprenda a declarar, preencher e exibir matrizes (arrays de duas dimensões) em C++ utilizando laços aninhados, estabelecendo o paralelo com a estrutura de matrizes do Portugol.', 3, 1, '2026-09-28 11:14:52', NULL, NULL),
	(54, 6, 'Strings e Manipulação de Texto em C++', 'Aprenda a trabalhar com o tipo de dado std::string em C++, incluindo a leitura de textos com espaços via getline(), métodos úteis como length(), concatenação e acesso a caracteres individuais.', 4, 1, '2026-09-28 11:16:03', NULL, NULL),
	(55, 6, 'Funções e Procedimentos em C++ (Passagem por Valor)', 'Aprenda a criar modularização no C++ utilizando funções com retorno de valores e procedimentos (funções void), entendendo a passagem de parâmetros por valor.', 5, 1, '2026-09-28 11:16:03', NULL, NULL),
	(56, 6, 'Passagem por Referência e Parâmetros em C++', 'Aprenda a utilizar a passagem por referência (&) em funções C++, permitindo alterar variáveis originais, otimizar o uso de memória e entender como vetores são automaticamente passados por referência.', 6, 1, '2026-09-28 11:17:39', NULL, NULL),
	(57, 6, 'Structs (Estruturas e Registros) em C++', 'Aprenda a criar tipos de dados customizados em C++ agrupando variáveis heterogêneas utilizando a palavra-chave struct, acessando campos através do operador ponto (.) e manipulando vetores de structs.', 7, 1, '2026-09-28 11:17:39', NULL, NULL),
	(58, 6, 'Vetores de Structs e Manipulação de Registros com Funções', 'Aprenda a integrar vetores e estruturas (structs) em C++, passando registros individuais ou arranjos completos de structs para funções por valor e referência constante.', 8, 1, '2026-09-28 11:19:40', NULL, NULL),
	(59, 6, 'Escopo de Variáveis, Constantes e Organização de Código em C++', 'Aprenda a gerenciar o escopo de variáveis (locais vs globais), utilizar a palavra-chave const para definição de constantes e organizar o fluxo do código seguindo as melhores práticas do C++.', 9, 1, '2026-09-28 11:19:40', NULL, NULL),
	(60, 6, 'Projeto Prático - Sistema Completo de Cadastro em C++', 'Consolide os conhecimentos do módulo criando um programa completo que utiliza structs, vetores, funções, passagem por referência e menus interativos para cadastrar, listar e buscar registros em C++.', 10, 1, '2026-09-28 12:03:10', NULL, NULL);
INSERT INTO `cadastro_usuario` (`id_usuario`, `nome_usuario`, `email_usuario`, `senha_usuario`, `tipo_usuario`, `datacadastro_usuario`, `token_recuperacao`, `token_expira`) VALUES
	(1, 'Abner Osti', '9123@fai.com.br', '$2y$10$JjxNoMk7krloQx.0QWc.WOjC.NwZ6N7Tmlqy4qEqsxQrH2TYw4DCa', 'ADMIN', '2026-08-26', NULL, NULL),
	(2, 'Abner Sarilho Osti', 'abnersarilhoosti@gmail.com', '$2y$10$hDT34Z5woM.JpTHn3WjfuuTDDy/WY5Uq5jDRdqVLXyHqJLBHF6W8m', 'ALUNO', '2026-10-01', NULL, NULL);
INSERT INTO `exercicios` (`id_exercicio`, `id_aula`, `tipo_exercicio`, `pergunta`, `feedback_erro`, `id_admin_criador`, `data_criacao`, `id_admin_editor`, `data_atualizacao`) VALUES
	(1, 1, 'multipla_escolha', 'Qual dos seguintes NÃO é um dos quatro pilares do Pensamento Computacional?', 'Lembre-se dos pilares: Decomposição, Padrões, Abstração e Algoritmos.', 1, '2026-08-26 10:35:18', NULL, NULL),
	(2, 1, 'completar_lacunas', 'O processo de quebrar um problema complexo em partes menores e mais fáceis de resolver chama-se _______.', 'Dica: Significa dividir ou separar as partes.', 1, '2026-08-26 10:35:18', NULL, NULL),
	(3, 1, 'ordenar_blocos', 'Ordene as etapas lógicas corretas para o pilar de construção de Algoritmos:', 'Pense em como você planeja um passo a passo.', 1, '2026-08-26 10:35:18', NULL, NULL),
	(4, 1, 'multipla_escolha', 'Ao focar apenas nas características essenciais de um problema e ignorar os detalhes desnecessários, estamos usando:', 'Ignorar o que não importa é o ato de abstrair.', 1, '2026-08-26 10:35:18', NULL, NULL),
	(5, 1, 'completar_lacunas', 'Um _______ é uma sequência finita de passos bem definidos para resolver um problema.', 'O resultado final do pensamento computacional costuma ser esta sequência de passos.', 1, '2026-08-26 10:35:18', NULL, NULL),
	(6, 1, 'ordenar_blocos', 'Coloque em ordem sequencial lógica a ação de "Atender ao Telefone":', 'Você não pode falar antes de tirar o telefone do ouvido ou do gancho.', 1, '2026-08-26 10:35:18', NULL, NULL),
	(7, 1, 'multipla_escolha', 'Identificar que uma receita de bolo e uma receita de torta seguem passos estruturados semelhantes é um exemplo de:', 'Procurar semelhanças é associado a padrões.', 1, '2026-08-26 10:35:18', NULL, NULL),
	(8, 1, 'completar_lacunas', 'O pensamento computacional é uma habilidade voltada primariamente para a resolução de _______.', 'O grande objetivo de pensar como a computação é solucionar algo.', 1, '2026-08-26 10:35:18', NULL, NULL),
	(9, 1, 'multipla_escolha', 'Quem pode utilizar as técnicas do pensamento computacional?', 'Computadores executam, mas quem projeta a lógica?', 1, '2026-08-26 10:35:18', NULL, NULL),
	(10, 1, 'ordenar_blocos', 'Ordene o ciclo básico de funcionamento de um algoritmo genérico:', 'Pense no fluxo: o que entra, o que é processado e o que sai.', 1, '2026-08-26 10:35:18', NULL, NULL),
	(11, 2, 'multipla_escolha', 'Se o seu objetivo é criar um jogo inteiro de computador, qual seria a primeira etapa aplicando a Decomposição?', 'Decompor é quebrar em partes menores antes de começar a fazer tudo de uma vez.', 1, '2026-08-26 10:46:46', NULL, NULL),
	(12, 2, 'completar_lacunas', 'Ao dividir um problema complexo em subproblemas menores, cada parte menor é chamada de _______.', 'Dica: É um problema menor ou um fragmento do desafio original.', 1, '2026-08-26 10:46:46', NULL, NULL),
	(13, 2, 'ordenar_blocos', 'Ordene as etapas corretas para decompor a tarefa de "Organizar uma Festa de Aniversário":', 'Pense na ordem lógica: planejar os convidados, comprar as coisas e depois arrumar.', 1, '2026-08-26 10:46:46', NULL, NULL),
	(14, 2, 'multipla_escolha', 'Qual é a principal vantagem de utilizarmos a decomposição logo no início de um projeto?', 'Pense na Teoria da Carga Cognitiva: problemas menores sobrecarregam menos a mente.', 1, '2026-08-26 10:46:46', NULL, NULL),
	(15, 2, 'completar_lacunas', 'Se tentarmos resolver um grande problema de uma só vez, sem dividi-lo, corremos o risco de sofrer uma sobrecarga _______.', 'Termo científico da psicologia cognitiva que estudamos na fundamentação do sistema.', 1, '2026-08-26 10:46:46', NULL, NULL),
	(16, 2, 'ordenar_blocos', 'Ordene a decomposição ideal para resolver o desenvolvimento de um sistema WEB:', 'O que vem primeiro? O banco de dados, o back-end ou as telas visuais?', 1, '2026-08-26 10:46:46', NULL, NULL),
	(17, 2, 'multipla_escolha', 'Ao decompor o desenvolvimento de um aplicativo de entregas (Delivery), qual destas partes seria um subproblema válido?', 'Procure uma funcionalidade isolada que faz parte do aplicativo.', 1, '2026-08-26 10:46:46', NULL, NULL),
	(18, 2, 'completar_lacunas', 'A decomposição nos ajuda a focar em uma pequena _______ por vez, aumentando a eficiência.', 'Palavra sinônimo de dever, atividade ou pedaço de trabalho.', 1, '2026-08-26 10:46:46', NULL, NULL),
	(19, 2, 'multipla_escolha', 'O que acontece se uma das partes decompostas de um problema ainda estiver muito complexa para ser resolvida?', 'Se algo ainda está grande, a regra de divisão continua valendo.', 1, '2026-08-26 10:46:46', NULL, NULL),
	(20, 2, 'ordenar_blocos', 'Ordene os passos para escovar os dentes, aplicando o conceito de decomposição das ações físicas:', 'Sequencie do início ao fim do processo.', 1, '2026-08-26 10:46:46', NULL, NULL),
	(21, 3, 'multipla_escolha', 'O que significa aplicar o "Reconhecimento de Padrões" no pensamento computacional?', 'Buscar semelhanças nos ajuda a usar soluções que já funcionaram antes.', 1, '2026-08-26 10:48:37', NULL, NULL),
	(22, 3, 'completar_lacunas', 'Ao identificar características comuns entre diferentes problemas, estamos encontrando um _______.', 'Dica: É uma repetição, um modelo ou uma constante que se repete.', 1, '2026-08-26 10:48:37', NULL, NULL),
	(23, 3, 'ordenar_blocos', 'Ordene as etapas corretas para reconhecer e usar um padrão na resolução de problemas:', 'Primeiro você observa vários problemas, acha a semelhança e depois cria a regra.', 1, '2026-08-26 10:48:37', NULL, NULL),
	(24, 3, 'multipla_escolha', 'Se você já sabe como criar um sistema de cadastro de Alunos, essa mesma lógica servirá para criar um cadastro de Clientes. Por quê?', 'Os dados mudam, mas a estrutura de salvar informações no banco segue o mesmo comportamento.', 1, '2026-08-26 10:48:37', NULL, NULL),
	(25, 3, 'completar_lacunas', 'Encontrar padrões nos permite _______ tempo, pois reutilizamos soluções de problemas conhecidos.', 'Pense no benefício gerado ao não precisar reinventar a roda do zero.', 1, '2026-08-26 10:48:37', NULL, NULL),
	(26, 3, 'ordenar_blocos', 'Coloque em ordem lógica a identificação do padrão na sequência numérica [2, 4, 6, 8, 10]:', 'Como descobrimos o comportamento e o próximo número da lista?', 1, '2026-08-26 10:48:37', NULL, NULL),
	(27, 3, 'multipla_escolha', 'Qual das alternativas descreve um padrão encontrado no comportamento de usuários em uma plataforma de e-commerce?', 'Padrões de comportamento geram tendências repetitivas de consumo.', 1, '2026-08-26 10:48:37', NULL, NULL),
	(28, 3, 'completar_lacunas', 'Na computação, o reconhecimento de padrões é a base para o desenvolvimento de algoritmos de Inteligência _______.', 'Área da tecnologia que aprende reconhecendo padrões em bilhões de dados.', 1, '2026-08-26 10:48:37', NULL, NULL),
	(29, 3, 'multipla_escolha', 'O que acontece se ignorarmos o reconhecimento de padrões ao desenvolver um sistema complexo?', 'Sem padrões, você precisará reescrever códigos parecidos dezenas de vezes.', 1, '2026-08-26 10:48:37', NULL, NULL),
	(30, 3, 'ordenar_blocos', 'Ordene o processo de automatização de uma linha de produção usando padrões:', 'Você analisa a repetição humana para depois programar o robô a fazer igual.', 1, '2026-08-26 10:48:37', NULL, NULL),
	(31, 4, 'multipla_escolha', 'O que é o pilar da "Abstração" no contexto do Pensamento Computacional?', 'Abstrair é filtrar: focar no que importa e ignorar os detalhes irrelevantes.', 1, '2026-08-26 10:49:25', NULL, NULL),
	(32, 4, 'completar_lacunas', 'O ato de ignorar os detalhes desnecessários de um problema para focar apenas no que é essencial chama-se _______.', 'Dica: É o nome deste terceiro pilar que estamos estudando.', 1, '2026-08-26 10:49:25', NULL, NULL),
	(33, 4, 'ordenar_blocos', 'Ordene as etapas lógicas para aplicar a Abstração ao criar o cadastro de usuários do seu TCC:', 'Identifique o problema geral, separe o que é essencial de coletar e ignore detalhes cosméticos.', 1, '2026-08-26 10:49:25', NULL, NULL),
	(34, 4, 'multipla_escolha', 'Ao projetar o mapa de um aplicativo de GPS, qual das seguintes informações deve ser ABSTRAÍDA (ocultada/ignorada)?', 'O motorista precisa ver caminhos transitáveis. Detalhes estéticos da calçada importam para dirigir?', 1, '2026-08-26 10:49:25', NULL, NULL),
	(35, 4, 'completar_lacunas', 'A abstração ajuda a reduzir a complexidade, evitando que o aluno sofra uma sobrecarga _______ ao programar.', 'Conceito da teoria de John Sweller que usamos para justificar a interface do sistema.', 1, '2026-08-26 10:49:25', NULL, NULL),
	(36, 4, 'ordenar_blocos', 'Coloque em ordem de relevância (do mais essencial ao totalmente irrelevante) os dados para um sistema bancário realizar um Pix:', 'O que o banco precisa obrigatoriamente validar para mover o dinheiro?', 1, '2026-08-26 10:49:25', NULL, NULL),
	(37, 4, 'multipla_escolha', 'Por que os modelos de simulação médica (como bonecos de treinamento) são considerados uma abstração da realidade?', 'Eles não têm órgãos reais, mas reproduzem fielmente os mecanismos necessários para o treino.', 1, '2026-08-26 10:49:25', NULL, NULL),
	(38, 4, 'completar_lacunas', 'Quando criamos uma representação simplificada de algo complexo do mundo real no código, estamos criando um _______.', 'Termo sinônimo de representação, padrão, protótipo ou maquete lógica.', 1, '2026-08-26 10:49:25', NULL, NULL),
	(39, 4, 'multipla_escolha', 'O que acontece se um desenvolvedor NÃO aplicar a abstração e tentar tratar todos os detalhes de um problema de uma vez?', 'Se colocar regras demais que não fazem parte do escopo, o código fica confuso e impossível de terminar.', 1, '2026-08-26 10:49:25', NULL, NULL),
	(40, 4, 'ordenar_blocos', 'Ordene as ações para criar uma representação abstrata de um "Carro" em um jogo de corrida:', 'Defina o conceito básico, filtre os atributos físicos necessários e descarte o que não afeta a jogabilidade.', 1, '2026-08-26 10:49:25', NULL, NULL),
	(41, 5, 'multipla_escolha', 'O que define um "Algoritmo" no contexto do Pensamento Computacional?', 'Um algoritmo é um guia prático, um passo a passo claro que leva a uma solução.', 1, '2026-08-26 11:33:56', NULL, NULL),
	(42, 5, 'completar_lacunas', 'Um algoritmo deve ser composto por uma sequência _______ de passos, ou seja, ele precisa ter um início e um fim.', 'Dica: O contrário de infinito.', 1, '2026-08-26 11:33:56', NULL, NULL),
	(43, 5, 'ordenar_blocos', 'Ordene a sequência lógica clássica de um algoritmo que calcula a média de duas notas de um aluno:', 'Pense no fluxo de dados: obter as notas, fazer o cálculo e mostrar o resultado.', 1, '2026-08-26 11:33:56', NULL, NULL),
	(44, 5, 'multipla_escolha', 'Por que a clareza e a precisão nas instruções são fundamentais ao escrever um algoritmo para um computador?', 'Computadores não interpretam duplas intenções; eles executam exatamente o que está escrito.', 1, '2026-08-26 11:33:56', NULL, NULL),
	(45, 5, 'completar_lacunas', 'A representação visual de um algoritmo por meio de formas geométricas (como retângulos e losangos) é chamada de _______.', 'Termo muito usado na lógica para desenhar o fluxo de um programa antes de codificar.', 1, '2026-08-26 11:33:56', NULL, NULL),
	(46, 5, 'ordenar_blocos', 'Coloque em ordem as instruções de um algoritmo simples para "Trocar uma Lâmpada Queimada":', 'Antes de colocar a nova, você precisa remover a antiga com segurança.', 1, '2026-08-26 11:33:56', NULL, NULL),
	(47, 5, 'multipla_escolha', 'Qual das seguintes opções do nosso cotidiano pode ser considerada um exemplo perfeito de algoritmo?', 'Pense em algo que você segue passo a passo de forma estrita para obter um resultado final.', 1, '2026-08-26 11:33:56', NULL, NULL),
	(48, 5, 'completar_lacunas', 'Antes de escrever o código em uma linguagem como C++, o desenvolvedor costuma estruturar a lógica em um idioma nativo chamado _______.', 'O intermediário entre o português e o código textual estruturado (você usará nos módulos 3 e 4).', 1, '2026-08-26 11:33:56', NULL, NULL),
	(49, 5, 'multipla_escolha', 'O que acontece se uma única instrução estiver fora da ordem correta dentro de um algoritmo?', 'O computador executará na ordem errada, gerando um resultado incorreto ou travando o sistema.', 1, '2026-08-26 11:33:56', NULL, NULL),
	(50, 5, 'ordenar_blocos', 'Ordene o algoritmo lógico para realizar um saque em um caixa eletrônico:', 'Você precisa validar o cartão e a senha antes de receber o dinheiro físico.', 1, '2026-08-26 11:33:56', NULL, NULL),
	(51, 6, 'multipla_escolha', 'O que significa dizer que um computador executa instruções de forma "sequencial"?', 'Pense em uma fila ou em uma leitura tradicional: um passo após o outro, de cima para baixo.', 1, '2026-08-26 11:35:01', NULL, NULL),
	(52, 6, 'completar_lacunas', 'Por padrão, os computadores leem e executam as linhas de código de cima para _______.', 'Dica: É a direção natural de leitura de um texto.', 1, '2026-08-26 11:35:01', NULL, NULL),
	(53, 6, 'ordenar_blocos', 'Ordene a sequência lógica exata que um programa deve seguir para calcular a idade de alguém:', 'Você não pode calcular a idade antes de perguntar o ano atual e o ano de nascimento.', 1, '2026-08-26 11:35:01', NULL, NULL),
	(54, 6, 'multipla_escolha', 'Considere o seguinte fluxo lógico de tarefas cotidianas: [1. Colocar o sapato] -> [2. Colocar a meia]. Por que essa sequência está errada para um pensamento sequencial correto?', 'O computador não consegue executar uma ação que dependa de um estado físico impossível na lógica anterior.', 1, '2026-08-26 11:35:01', NULL, NULL),
	(55, 6, 'completar_lacunas', 'Em uma estrutura sequencial pura, nenhuma instrução pode ser pulada ou executada fora da _______ correta.', 'Palavra relacionada ao alinhamento, ordenação ou cronologia dos passos.', 1, '2026-08-26 11:35:01', NULL, NULL),
	(56, 6, 'ordenar_blocos', 'Coloque em ordem sequencial as instruções de um programa que prepara um café instantâneo:', 'Pense na ordem física e cronológica dos acontecimentos.', 1, '2026-08-26 11:35:01', NULL, NULL),
	(57, 6, 'multipla_escolha', 'Se um programa tem 3 linhas de código (Linha 1, Linha 2 e Linha 3), qual será a ordem exata de execução do processador?', 'A execução padrão é estritamente linear.', 1, '2026-08-26 11:35:01', NULL, NULL),
	(58, 6, 'completar_lacunas', 'A execução sequencial é a estrutura mais básica e fundamental no desenvolvimento de um _______.', 'Termo usado para se referir ao código, receita ou sequência de passos lógicos.', 1, '2026-08-26 11:35:01', NULL, NULL),
	(59, 6, 'multipla_escolha', 'O que acontece se alterarmos a ordem das linhas em um algoritmo de divisão matemática, colocando a exibição do resultado antes da operação matemática?', 'O computador tentará mostrar algo que ainda não foi calculado, gerando um erro de lógica.', 1, '2026-08-26 11:35:01', NULL, NULL),
	(60, 6, 'ordenar_blocos', 'Ordene a sequência lógica para um sistema que valida o login de um usuário:', 'O sistema primeiro lê os dados, depois processa/compara e por fim dá a resposta.', 1, '2026-08-26 11:35:01', NULL, NULL),
	(61, 7, 'multipla_escolha', 'Por que analisar atividades do dia a dia (como fazer um café) ajuda no aprendizado de programação?', 'A nossa rotina é cheia de passos ordenados e condições, exatamente como um software funciona.', 1, '2026-08-26 12:23:50', NULL, NULL),
	(62, 7, 'completar_lacunas', 'Mapear passos lógicos de tarefas comuns mostra que programar é apenas traduzir a nossa _______ para a linguagem dos computadores.', 'Dica: Capacidade humana de pensar de forma coerente e estruturada.', 1, '2026-08-26 12:23:50', NULL, NULL),
	(63, 7, 'ordenar_blocos', 'Ordene a sequência lógica do cotidiano para a tarefa de "Lavar a Louça":', 'Pense na ordem prática de ensaboar antes de enxaguar.', 1, '2026-08-26 12:23:50', NULL, NULL),
	(64, 7, 'multipla_escolha', 'Se o seu despertador toca e você tem a seguinte regra: "Se estiver chovendo, vou de ônibus; senão, vou a pé". Que conceito lógico você está aplicando?', 'Esta é uma tomada de decisão baseada em uma condição do ambiente.', 1, '2026-08-26 12:23:50', NULL, NULL),
	(65, 7, 'completar_lacunas', 'Quando seguimos uma receita de bolo estritamente passo a passo, estamos executando um _______ no mundo real.', 'Termo que aprendemos na aula 5 e que se aplica perfeitamente a receitas.', 1, '2026-08-26 12:23:50', NULL, NULL),
	(66, 7, 'ordenar_blocos', 'Ordene o fluxo lógico para a ação de "Atravessar uma Rua Movimentada":', 'Você precisa olhar para os lados e avaliar o risco antes de dar o primeiro passo.', 1, '2026-08-26 12:23:50', NULL, NULL),
	(67, 7, 'multipla_escolha', 'Qual das seguintes situações cotidianas representa uma quebra de lógica (um "bug" na vida real)?', 'Um bug acontece quando uma ação tenta ser executada sem que os pré-requisitos necessários existam.', 1, '2026-08-26 12:23:50', NULL, NULL),
	(68, 7, 'completar_lacunas', 'Em programação, criar regras baseadas em "SE acontecer isso, ENTÃO faça aquilo" simula as nossas _______ diárias.', 'Palavra relacionada às escolhas que fazemos a todo momento.', 1, '2026-08-26 12:23:50', NULL, NULL),
	(69, 7, 'multipla_escolha', 'Ao organizar sua mochila escolar separando os materiais por matéria e descartando papéis velhos, quais pilares você usou?', 'Você dividiu a tarefa (decomposição) e filtrou o que não importava (abstração).', 1, '2026-08-26 12:23:50', NULL, NULL),
	(70, 7, 'ordenar_blocos', 'Ordene os passos lógicos que você faz antes de sair de casa para o trabalho/faculdade:', 'Você se arruma primeiro, pega seus pertences fundamentais e depois tranca o local.', 1, '2026-08-26 12:23:50', NULL, NULL),
	(71, 8, 'multipla_escolha', 'No contexto do fluxo de um programa, o que define uma "Entrada" (Input)?', 'Input é todo dado que vem de fora e é enviado para dentro do sistema processar.', 1, '2026-08-26 12:24:24', NULL, NULL),
	(72, 8, 'completar_lacunas', 'Quando um sistema exibe o resultado de um cálculo na tela para o usuário, ele realizou uma operação de _______.', 'Dica: É o dado saindo do sistema (termo em português ou inglês "output").', 1, '2026-08-26 12:24:24', NULL, NULL),
	(73, 8, 'ordenar_blocos', 'Ordene o fluxo correto de dados em um sistema que calcula o desconto de um produto:', 'Siga a ordem lógica: capturar o valor, aplicar o cálculo interno e depois exibir.', 1, '2026-08-26 12:24:24', NULL, NULL),
	(74, 8, 'multipla_escolha', 'Qual dos seguintes componentes físicos do computador é considerado EXCLUSIVAMENTE um dispositivo de Entrada (Input)?', 'Pense em qual periférico serve apenas para enviar informações para o computador, sem exibir respostas físicas.', 1, '2026-08-26 12:24:24', NULL, NULL),
	(75, 8, 'completar_lacunas', 'Para que um algoritmo possa calcular a soma de dois números, ele precisa primeiro receber esses valores através de um _______.', 'Termo em inglês para a entrada de dados.', 1, '2026-08-26 12:24:24', NULL, NULL),
	(76, 8, 'ordenar_blocos', 'Classifique e ordene os elementos de um sistema de caixa eletrônico (do Input inicial ao Output final):', 'O que você coloca no caixa primeiro e o que ele te devolve no final?', 1, '2026-08-26 12:24:24', NULL, NULL),
	(77, 8, 'multipla_escolha', 'Se um sistema de som automotivo recebe o sinal de um pen drive com músicas e toca o áudio nos alto-falantes, o que representa a Saída (Output)?', 'A saída é o resultado final perceptível gerado pelo sistema para o ambiente externo.', 1, '2026-08-26 12:24:24', NULL, NULL),
	(78, 8, 'completar_lacunas', 'O monitor de vídeo e a impressora são exemplos clássicos de dispositivos de _______.', 'Eles recebem dados processados pelo computador e os mostram/entregam para nós.', 1, '2026-08-26 12:24:24', NULL, NULL),
	(79, 8, 'multipla_escolha', 'O que aconteceria se um algoritmo de calculadora tivesse apenas comandos de Saída (Output) e nenhum comando de Entrada?', 'Sem entrada, o sistema não recebe dados dinâmicos do usuário para processar.', 1, '2026-08-26 12:24:24', NULL, NULL),
	(80, 8, 'ordenar_blocos', 'Ordene o ciclo de funcionamento de uma inteligência artificial que gera imagens a partir de textos:', 'Primeiro o usuário digita a ideia, a IA processa e depois renderiza o visual.', 1, '2026-08-26 12:24:24', NULL, NULL),
	(81, 9, 'multipla_escolha', 'O que é uma "Tomada de Decisão" (estrutura condicional) em um algoritmo?', 'Tomar uma decisão significa avaliar uma condição e escolher qual caminho o código deve seguir.', 1, '2026-08-26 12:26:20', NULL, NULL),
	(82, 9, 'completar_lacunas', 'A estrutura condicional básica na lógica de programação é representada pelas palavras "_______" e "Senão".', 'Dica: É a palavra usada para iniciar um teste de condição em português.', 1, '2026-08-26 12:26:20', NULL, NULL),
	(83, 9, 'ordenar_blocos', 'Ordene o fluxo de decisão de um algoritmo que verifica se uma pessoa pode votar (Idade mínima: 16 anos):', 'Primeiro o sistema analisa a idade, testa a condição e depois exibe o resultado correspondente.', 1, '2026-08-26 12:26:20', NULL, NULL),
	(84, 9, 'multipla_escolha', 'Considere a regra: "SE a nota do aluno for maior ou igual a 7, ele está Aprovado; SENÃO, está Reprovado". Se um aluno tirou nota 6, qual será a saída do algoritmo?', 'Como 6 não é maior nem igual a 7, o algoritmo cairá obrigatoriamente no bloco do Senão.', 1, '2026-08-26 12:26:20', NULL, NULL),
	(85, 9, 'completar_lacunas', 'O bloco "Senão" em um algoritmo só será executado se a condição inicial do "Se" for _______.', 'Pense no valor lógico (Verdadeiro ou Falso) que faz o caminho alternativo ser acionado.', 1, '2026-08-26 12:26:20', NULL, NULL),
	(86, 9, 'ordenar_blocos', 'Ordene os blocos lógicos de um sistema de login que valida a senha de um usuário:', 'Configure a estrutura lógica iniciando pelo teste da condição até as respostas possíveis.', 1, '2026-08-26 12:26:20', NULL, NULL),
	(87, 9, 'multipla_escolha', 'Qual das seguintes situações do dia a dia descreve PERFEITAMENTE uma tomada de decisão condicional composta?', 'Procure uma ação que apresente uma condição clara e ofereça dois caminhos bem definidos (um para sim, um para não).', 1, '2026-08-26 12:26:20', NULL, NULL),
	(88, 9, 'completar_lacunas', 'Para avaliar se uma condição é verdadeira, os algoritmos utilizam operadores _______ como maior que, menor que ou igual.', 'Palavra relacionada a comparações ou relações matemáticas.', 1, '2026-08-26 12:26:20', NULL, NULL),
	(89, 9, 'multipla_escolha', 'O que acontece se uma estrutura condicional "Se" não tiver um bloco "Senão" associado?', 'O Senão não é obrigatório; se a condição for falsa, o programa simplesmente continua sua execução normal.', 1, '2026-08-26 12:26:20', NULL, NULL),
	(90, 9, 'ordenar_blocos', 'Ordene o algoritmo de um sistema de sensor de presença para acendimento de lâmpadas:', 'Mapeie o fluxo desde a detecção do movimento até a decisão de ligar ou desligar a luz.', 1, '2026-08-26 12:26:20', NULL, NULL),
	(91, 10, 'multipla_escolha', 'Ao revisar o Pensamento Computacional, qual é a ordem ideal de aplicação dos pilares ao enfrentar um novo problema?', 'A sequência clássica começa dividindo o problema, passa pela análise, filtragem e termina na solução estruturada.', 1, '2026-08-26 12:27:33', NULL, NULL),
	(92, 10, 'completar_lacunas', 'A combinação de instruções sequenciais, entradas, saídas e tomadas de decisão forma a base de qualquer _______ estruturado.', 'Dica: É o conjunto de passos lógicos que resolve o problema (termo central do pilar 4).', 1, '2026-08-26 12:27:33', NULL, NULL),
	(93, 10, 'ordenar_blocos', 'Ordene o fluxo lógico macro de um sistema completo de votação eletrônica:', 'Organize do recebimento dos dados brutos, passando pelas regras de negócio até o resultado consolidado.', 1, '2026-08-26 12:27:33', NULL, NULL),
	(94, 10, 'multipla_escolha', 'Uma empresa quer criar um sistema para recomendar filmes. Ela analisa o histórico de navegação (Padrões) e ignora a cor da TV do usuário (Abstração). O que falta para fechar o ciclo do Pensamento Computacional?', 'Se ela já analisou e filtrou, agora precisa criar a sequência de passos que gera a recomendação.', 1, '2026-08-26 12:27:33', NULL, NULL),
	(95, 10, 'completar_lacunas', 'Erros na lógica ou na ordem de execução de um fluxo que geram resultados inesperados são chamados popularmente de _______.', 'Termo em inglês muito usado na área de tecnologia para representar falhas.', 1, '2026-08-26 12:27:33', NULL, NULL),
	(96, 10, 'ordenar_blocos', 'Ordene as etapas de resolução de problemas, do nível mais abstrato/humano até a execução da máquina:', 'O scaffolding pedagógico do seu TCC vai do conceito puro até a linguagem de programação final.', 1, '2026-08-26 12:27:33', NULL, NULL),
	(97, 10, 'multipla_escolha', 'Qual das seguintes afirmações resume melhor a relação entre Pensamento Computacional e linguagens de programação (como C++)?', 'A lógica vem antes da sintaxe de qualquer linguagem de programação.', 1, '2026-08-26 12:27:33', NULL, NULL),
	(98, 10, 'completar_lacunas', 'O objetivo de aplicar scaffolding e gerenciar a carga cognitiva no aprendizado de lógica é evitar a _______ mental do estudante.', 'Palavra sinônimo de esgotamento, saturação ou fadiga por excesso de informações.', 1, '2026-08-26 12:27:33', NULL, NULL),
	(99, 10, 'multipla_escolha', 'Imagine um algoritmo que calcula o imposto de renda. Se o usuário esquecer de digitar o seu salário, qual parte do fluxo falhou?', 'O salário é o dado essencial que precisa vir de fora para o programa funcionar.', 1, '2026-08-26 12:27:33', NULL, NULL),
	(100, 10, 'ordenar_blocos', 'Ordene o ciclo de vida completo de uma tomada de decisão dentro de um fluxo lógico de revisão:', 'Identifique a pergunta, faça o teste lógico e separe as consequências.', 1, '2026-08-26 12:27:33', NULL, NULL),
	(101, 11, 'multipla_escolha', 'Por que a transição direta da linguagem falada para uma linguagem de programação complexa pode causar sobrecarga cognitiva?', 'Lembrar regras de sintaxe rígidas junto com a lógica de resolução do problema divide a atenção do estudante.', 1, '2026-09-12 15:24:05', NULL, NULL),
	(102, 11, 'completar_lacunas', 'O _______ atua como uma ponte intermediária entre a forma como os humanos pensam e a forma rigorosa como as máquinas executam ordens.', 'É a ferramenta estruturada em português que usaremos antes de digitar código real.', 1, '2026-09-12 15:24:05', NULL, NULL),
	(103, 11, 'ordenar_blocos', 'Ordene a evolução do nível de abstração no aprendizado de programação, da linguagem humana até a máquina:', 'Comece na ideia informal e advance gradativamente até a linguagem mais técnica.', 1, '2026-09-12 15:24:05', NULL, NULL),
	(104, 11, 'multipla_escolha', 'Qual é a principal limitação de escrever um algoritmo apenas em português falado (linguagem natural)?', 'A linguagem humana possui ambiguidades e termos que o computador não consegue interpretar de forma exata.', 1, '2026-09-12 15:24:05', NULL, NULL),
	(105, 11, 'completar_lacunas', 'Para evitar ambiguidades na interpretação do computador, os algoritmos precisam ser escritos de forma _____.', 'Termo que indica algo preciso, sem margem para duplas interpretações.', 1, '2026-09-12 15:24:05', NULL, NULL),
	(106, 11, 'ordenar_blocos', 'Ordene os passos para transformar um pensamento informal em um passo a passo pronto para o pseudocódigo:', 'Primeiro entenda a ideia, depois organize em passos sequenciais e por fim remova trechos ambíguos.', 1, '2026-09-12 15:24:05', NULL, NULL),
	(107, 11, 'multipla_escolha', 'Ao comparar uma receita de bolo com um algoritmo intermediário, qual característica ambos têm em comum?', 'Ambos dependem de uma sequência de instruções ordenadas que devem ser seguidas para chegar ao resultado.', 1, '2026-09-12 15:24:05', NULL, NULL),
	(108, 11, 'completar_lacunas', 'A padronização das instruções em um algoritmo reduz a ambiguidade e diminui a carga _____ do aluno.', 'Refere-se ao esforço mental necessário para processar as informações.', 1, '2026-09-12 15:24:05', NULL, NULL),
	(109, 11, 'ordenar_blocos', 'Ordene a transformação da instrução informal "Pede a idade da pessoa" em uma instrução estruturada:', 'Pense na evolução do texto informal até chegar ao formato padrão de instrução.', 1, '2026-09-12 15:24:05', NULL, NULL),
	(110, 11, 'multipla_escolha', 'Qual é o papel do Portugol/Pseudocódigo nas primeiras semanas do aprendizado de lógica?', 'Sua função principal é focar na construção da solução lógica sem a cobrança de erros de pontuação de linguagens formais.', 1, '2026-09-12 15:24:05', NULL, NULL),
	(111, 12, 'multipla_escolha', 'O que caracteriza a execução sequencial de um algoritmo básico?', 'Em um algoritmo padrão sem desvios, as instruções são lidas linha por linha, de cima para baixo.', 1, '2026-09-12 15:26:13', NULL, NULL),
	(112, 12, 'completar_lacunas', 'A instrução que marca o ponto exato onde o computador deve começar a ler o algoritmo é o _______.', 'Refere-se ao bloco de abertura/inicialização do fluxo.', 1, '2026-09-12 15:26:13', NULL, NULL),
	(113, 12, 'ordenar_blocos', 'Ordene o esqueleto estrutural primário de qualquer programa em pseudocódigo:', 'Todo programa segue a sequência: Abertura do programa -> Instruções internas -> Fechamento.', 1, '2026-09-12 15:26:13', NULL, NULL),
	(114, 12, 'multipla_escolha', 'O que acontece se um algoritmo não possuir uma demarcação clara de "Fim"?', 'Sem uma sinalização de término, a máquina não sabe onde encerrar o processamento das instruções.', 1, '2026-09-12 15:26:13', NULL, NULL),
	(115, 12, 'completar_lacunas', 'O conjunto de linhas contidas entre o início e o fim de um algoritmo é chamado de _____ de código.', 'É o termo usado para definir a região onde ficam as instruções.', 1, '2026-09-12 15:26:13', NULL, NULL),
	(116, 12, 'ordenar_blocos', 'Ordene as etapas de preparação de uma tarefa simples (Fazer um Café) dentro de um fluxo estruturado:', 'Pense no fluxo sequencial correto: Inicio -> Ações em ordem -> Fim.', 1, '2026-09-12 15:26:13', NULL, NULL),
	(117, 12, 'multipla_escolha', 'Por que a ordem das linhas altera o resultado final de um algoritmo?', 'O computador executa as ordens estritamente na sequência em que foram escritas.', 1, '2026-09-12 15:26:13', NULL, NULL),
	(118, 12, 'completar_lacunas', 'A palavra reservada que sinaliza ao computador que a execução foi concluída é o _______.', 'É o comando de encerramento do algoritmo.', 1, '2026-09-12 15:26:13', NULL, NULL),
	(119, 12, 'ordenar_blocos', 'Ordene as instruções para trocar um pneu furado de forma sequencialmente correta:', 'Ações físicas dependem de pré-requisitos antes de serem executadas.', 1, '2026-09-12 15:26:13', NULL, NULL),
	(120, 12, 'multipla_escolha', 'Se invertermos a ordem das instruções "Ligar o carro" e "Entrar no carro", o que acontecerá na lógica?', 'Uma ação só pode ser realizada se os seus pré-requisitos lógicos já tiverem sido concluídos.', 1, '2026-09-12 15:26:13', NULL, NULL),
	(121, 13, 'multipla_escolha', 'Qual analogia do mundo real melhor descreve o funcionamento de uma variável no computador?', 'Pense em algo que possui um nome (etiqueta) e guarda um conteúdo que pode mudar com o tempo.', 1, '2026-09-12 15:32:27', NULL, NULL),
	(122, 13, 'completar_lacunas', 'O nome que damos a uma posição da memória para guardar um valor é chamado de _______.', 'Termo usado para identificar o local onde armazenamos dados alteráveis.', 1, '2026-09-12 15:32:27', NULL, NULL),
	(123, 13, 'ordenar_blocos', 'Ordene o ciclo de vida de um dado dentro de uma variável durante a execução de um programa:', 'Pense em criar o espaço, colocar um valor inicial e depois atualizar esse valor.', 1, '2026-09-12 15:32:27', NULL, NULL),
	(124, 13, 'multipla_escolha', 'Por que dizemos que o conteúdo de uma variável é "volátil" ou "mutável"?', 'Ao atribuir um novo valor a uma variável, o valor antigo é substituído pelo novo.', 1, '2026-09-12 15:32:27', NULL, NULL),
	(125, 13, 'completar_lacunas', 'Quando guardamos um novo dado dentro de uma variável que já tinha valor, o valor antigo é _______.', 'Imagine colocar um objeto novo dentro de uma caixa pequena que só cabe um item.', 1, '2026-09-12 15:32:27', NULL, NULL),
	(126, 13, 'ordenar_blocos', 'Ordene as instruções para atualizar a pontuação de um jogador em um jogo:', 'Primeiro defina os pontos iniciais, depois adicione a nova pontuação.', 1, '2026-09-12 15:32:27', NULL, NULL),
	(127, 13, 'multipla_escolha', 'Se temos a variável `pontos = 10` e logo em seguida executamos `pontos = 15`, qual valor estará guardado na caixa `pontos`?', 'O último valor atribuído sempre substitui o conteúdo anterior da memória.', 1, '2026-09-12 15:32:27', NULL, NULL),
	(128, 13, 'completar_lacunas', 'Dar um nome claro para uma variável (como `idade` em vez de `x`) ajuda a reduzir a carga _______ de quem lê o código.', 'Refere-se ao esforço de entendimento e clareza mental.', 1, '2026-09-12 15:32:27', NULL, NULL),
	(129, 13, 'ordenar_blocos', 'Ordene a sequência de manipulação de saldo em uma conta bancária simples:', 'Siga a lógica: Saldo inicial -> Recebimento de depósito -> Saldo atualizado.', 1, '2026-09-12 15:32:27', NULL, NULL),
	(130, 13, 'multipla_escolha', 'Qual das opções abaixo é um bom exemplo de nome de variável para guardar a nota de um aluno?', 'Nomes de variáveis devem ser expressivos e indicar exatamente o tipo de conteúdo guardado.', 1, '2026-09-12 15:32:27', NULL, NULL),
	(131, 14, 'multipla_escolha', 'Qual é o tipo de dado mais adequado para armazenar a quantidade de alunos em uma sala de aula?', 'Contagens de itens inteiros não possuem casas decimais.', 1, '2026-09-12 15:34:55', NULL, NULL),
	(132, 14, 'completar_lacunas', 'Valores do tipo _______ representam dados textuais, como nomes, endereços ou mensagens.', 'Termo usado para definir sequências de letras ou caracteres.', 1, '2026-09-12 15:34:55', NULL, NULL),
	(133, 14, 'ordenar_blocos', 'Ordene as variáveis abaixo categorizando do tipo TEXTO até o tipo LÓGICO:', 'A sequência esperada é: Texto -> Inteiro -> Real -> Lógico.', 1, '2026-09-12 15:34:55', NULL, NULL),
	(134, 14, 'multipla_escolha', 'Se precisamos guardar o preço de um produto (ex: R$ 19,90), qual tipo de dado devemos utilizar?', 'Valores numéricos que contêm vírgula ou ponto decimal pertencem ao grupo dos números reais.', 1, '2026-09-12 15:34:55', NULL, NULL),
	(135, 14, 'completar_lacunas', 'O tipo de dado que aceita apenas dois valores possíveis (Verdadeiro ou Falso) é chamado de _______.', 'Refere-se ao tipo usado para testes de decisão e condições.', 1, '2026-09-12 15:34:55', NULL, NULL),
	(136, 14, 'ordenar_blocos', 'Ordene o algoritmo simples organizando a declaração das variáveis por tipo antes da atribuição de valores:', 'Defina o tipo das caixas primeiro, depois atribua os dados correspondentes.', 1, '2026-09-12 15:34:55', NULL, NULL),
	(137, 14, 'multipla_escolha', 'Por que não devemos guardar o número do telefone de um usuário em um tipo de dado puramente numérico (Inteiro)?', 'Telefones podem conter caracteres especiais como parenteses e traços, além de não serem usados para cálculos matemáticos.', 1, '2026-09-12 15:34:55', NULL, NULL),
	(138, 14, 'completar_lacunas', 'Números sem casas decimais (como 5, 0 ou -12) pertencem ao tipo _______.', 'Tipo numérico sem fração.', 1, '2026-09-12 15:34:55', NULL, NULL),
	(139, 14, 'ordenar_blocos', 'Ordene a associação de valores com seus respectivos tipos em ordem crescente de complexidade de dados:', 'Ordene de: Lógico -> Inteiro -> Real -> Texto.', 1, '2026-09-12 15:34:55', NULL, NULL),
	(140, 14, 'multipla_escolha', 'O valor "Verdadeiro" em um campo chamado `usuario_ativo` pertence a qual tipo de dado?', 'Tipos de confirmação de estado binário são lógicos.', 1, '2026-09-12 15:34:55', NULL, NULL),
	(141, 15, 'multipla_escolha', 'Qual é a função primária do comando `Escreva` em um programa em pseudocódigo?', 'Pense na ação de mostrar ou imprimir algo na tela para a pessoa que está usando o programa.', 1, '2026-09-12 15:37:51', NULL, NULL),
	(142, 15, 'completar_lacunas', 'O comando utilizado em pseudocódigo para capturar uma informação do teclado e salvá-la em uma variável é o _______.', 'Ação de entrada de dados no sistema.', 1, '2026-09-12 15:37:51', NULL, NULL),
	(143, 15, 'ordenar_blocos', 'Ordene o fluxo lógico de uma interação de boas-vindas simples com o usuário:', 'Primeiro solicite o dado, depois leia e por fim mostre a resposta personalizada.', 1, '2026-09-12 15:37:51', NULL, NULL),
	(144, 15, 'multipla_escolha', 'Analise o comando: `Leia(idade)`. O que o computador faz ao passar por essa linha?', 'O programa faz uma pausa no processamento aguardando a interação do usuário via teclado.', 1, '2026-09-12 15:37:51', NULL, NULL),
	(145, 15, 'completar_lacunas', 'Ao utilizar a instrução `Escreva("Olá")`, o texto entre aspas é exibido de forma _______ na tela.', 'Indica que o conteúdo dentro das aspas é impresso exatamente como foi escrito.', 1, '2026-09-12 15:37:51', NULL, NULL),
	(146, 15, 'ordenar_blocos', 'Ordene o algoritmo para ler o ano de nascimento de um usuário e exibi-lo formatado:', 'Organize na ordem: Inicio -> Mensagem -> Leitura -> Saída -> Fim.', 1, '2026-09-12 15:37:51', NULL, NULL),
	(147, 15, 'multipla_escolha', 'Se executarmos `Escreva(nome)` sem aspas, o que o programa exibirá na tela?', 'Sem aspas, a instrução faz referência ao conteúdo guardado dentro da variável.', 1, '2026-09-12 15:37:51', NULL, NULL),
	(148, 15, 'completar_lacunas', 'A combinação do comando `Escreva` seguido pelo comando `Leia` forma a estrutura clássica de solicitação e _______ de dados.', 'O ato de coletar/receber a informação.', 1, '2026-09-12 15:37:51', NULL, NULL),
	(149, 15, 'ordenar_blocos', 'Ordene os blocos para formar um algoritmo em pseudocódigo que leia duas notas e exiba os valores na tela:', 'Siga o fluxo sequencial e lógico de atribuições de entrada e saída.', 1, '2026-09-12 15:37:51', NULL, NULL),
	(150, 15, 'multipla_escolha', 'Qual é o erro do seguinte trecho: `Leia("Digite seu nome")`?', 'O comando de leitura exige uma variável como destino do dado, não um texto fixo entre aspas.', 1, '2026-09-12 15:37:51', NULL, NULL),
	(151, 16, 'multipla_escolha', 'Qual é o símbolo utilizado no pseudocódigo para representar a operação de multiplicação entre dois valores ou variáveis?', 'O símbolo de multiplicação em programação difere do "x" usado na matemática tradicional.', 1, '2026-09-12 15:39:13', NULL, NULL),
	(152, 16, 'completar_lacunas', 'O operador utilizado para realizar a divisão entre dois números em pseudocódigo é a _______.', 'Símbolo gráfico inclinado para a direita.', 1, '2026-09-12 15:39:13', NULL, NULL),
	(153, 16, 'ordenar_blocos', 'Ordene o algoritmo para calcular a média aritmética simples de duas notas inseridas pelo usuário:', 'Programe na ordem: Entrada de dados -> Cálculo matemático -> Saída do resultado.', 1, '2026-09-12 15:39:13', NULL, NULL),
	(154, 16, 'multipla_escolha', 'Analise a instrução: `resultado <- 10 + 2 * 5`. Qual será o valor armazenado na variável `resultado`?', 'Lembre-se da ordem de precedência matemática: multiplicações e divisões são resolvidas antes de somas e subtrações.', 1, '2026-09-12 15:39:13', NULL, NULL),
	(155, 16, 'completar_lacunas', 'Para alterar a ordem de precedência em uma expressão matemática no pseudocódigo, devemos utilizar _______.', 'Símbolos usados para agrupar operações que devem ser executadas primeiro.', 1, '2026-09-12 15:39:13', NULL, NULL),
	(156, 16, 'ordenar_blocos', 'Ordene as instruções para calcular o valor de um desconto de 10% sobre o preço de um produto:', 'Obtenha o valor original, aplique o cálculo percentual e exiba o preço final.', 1, '2026-09-12 15:39:13', NULL, NULL),
	(157, 16, 'multipla_escolha', 'O que acontece ao tentar executar a operação `resultado <- 15 / 0` em um algoritmo?', 'Divisão por zero é uma operação matematicamente indefinida na computação.', 1, '2026-09-12 15:39:13', NULL, NULL),
	(158, 16, 'completar_lacunas', 'O símbolo `<-` é chamado de operador de _______ e guarda o resultado da expressão da direita na variável da esquerda.', 'Ação de atribuir/definir o valor de uma caixa de memória.', 1, '2026-09-12 15:39:13', NULL, NULL),
	(159, 16, 'ordenar_blocos', 'Ordene os blocos para calcular a área de um retângulo (base * altura):', 'Siga o fluxo estruturado: Início -> Leituras -> Cálculo -> Exibição -> Fim.', 1, '2026-09-12 15:39:13', NULL, NULL),
	(160, 16, 'multipla_escolha', 'Qual expressão em pseudocódigo calcula corretamente a soma de `a` e `b` dividida por 2?', 'Para que a soma ocorra antes da divisão, ela precisa estar agrupada entre parênteses.', 1, '2026-09-12 15:39:13', NULL, NULL),
	(161, 17, 'multipla_escolha', 'Qual é o objetivo principal de uma estrutura condicional `Se` em um algoritmo?', 'Pense na capacidade do programa de escolher se executa ou ignora um bloco de comandos.', 1, '2026-09-12 15:41:22', NULL, NULL),
	(162, 17, 'completar_lacunas', 'A palavra reservada que indica o início do bloco de código a ser executado caso a condição seja verdadeira é o _______.', 'Comando que complementa o teste condicional Se.', 1, '2026-09-12 15:41:22', NULL, NULL),
	(163, 17, 'ordenar_blocos', 'Ordene o algoritmo simples que verifica se uma pessoa é maior de idade:', 'Monte na sequência: Entrada da idade -> Teste condicional -> Mensagem de resposta.', 1, '2026-09-12 15:41:22', NULL, NULL),
	(164, 17, 'multipla_escolha', 'Qual operador relacional representa a comparação "Maior ou igual a" em pseudocódigo?', 'Símbolo composto usado para testar se um valor ultrapassa ou se iguala a outro.', 1, '2026-09-12 15:41:22', NULL, NULL),
	(165, 17, 'completar_lacunas', 'O resultado de uma comparação condicional dentro de um comando `Se` é sempre um valor do tipo _______.', 'Tipo de dado que só pode ser Verdadeiro ou Falso.', 1, '2026-09-12 15:41:22', NULL, NULL),
	(166, 17, 'ordenar_blocos', 'Ordene as linhas para verificar se o saldo de uma conta é suficiente para efetuar um saque:', 'Siga o fluxo: Início -> Leitura do saldo -> Teste da condição -> Aviso na tela -> Fim.', 1, '2026-09-12 15:41:22', NULL, NULL),
	(167, 17, 'multipla_escolha', 'Se a condição do comando `Se` for Falsa e não houver um bloco `Senao`, o que o programa fará?', 'Sem alternativa para o caso Falso, o fluxo apenas salta a instrução.', 1, '2026-09-12 15:41:22', NULL, NULL),
	(168, 17, 'completar_lacunas', 'Para fechar o bloco de instruções aberto pelo comando `Se`, utilizamos a instrução _______.', 'Demarca o término do teste condicional.', 1, '2026-09-12 15:41:22', NULL, NULL),
	(169, 17, 'ordenar_blocos', 'Ordene o algoritmo que concede um prêmio caso a pontuação do jogador seja superior a 100 pontos:', 'Defina o fluxo: Leitura dos pontos -> Verificação condicional -> Mensagem do prêmio -> Fechamento.', 1, '2026-09-12 15:41:22', NULL, NULL),
	(170, 17, 'multipla_escolha', 'Qual dos operadores abaixo verifica se dois valores são exatamente iguais em um teste condicional?', 'Símbolo usado para comparar a igualdade de duas variáveis.', 1, '2026-09-12 15:41:22', NULL, NULL),
	(171, 18, 'multipla_escolha', 'Qual é a principal função do bloco `Senao` em uma estrutura condicional composta?', 'Pense no que o programa deve fazer quando o teste do `Se` não for satisfeito (for Falso).', 1, '2026-09-12 15:47:29', NULL, NULL),
	(172, 18, 'completar_lacunas', 'Em uma estrutura `Se-Entao-Senao`, as instruções do bloco `Senao` só são executadas quando a condição for _______.', 'Resultado de um teste condicional que não é Verdadeiro.', 1, '2026-09-12 15:47:29', NULL, NULL),
	(173, 18, 'ordenar_blocos', 'Ordene o algoritmo que verifica se um aluno foi Aprovado ou Reprovado com base na nota 7:', 'Siga o fluxo: Início -> Leitura -> Se (Aprovado) -> Senão (Reprovado) -> FimSe.', 1, '2026-09-12 15:47:29', NULL, NULL),
	(174, 18, 'multipla_escolha', 'O que acontece com o bloco `Entao` quando a condição avaliada pelo `Se` resulta em Falso?', 'O computador ignora o bloco verdadeiro e salta direto para a alternativa.', 1, '2026-09-12 15:47:29', NULL, NULL),
	(175, 18, 'completar_lacunas', 'O comando `Senao` elimina a necessidade de escrever dois comandos `_______` simples para testar condições opostas.', 'Estrutura condicional simples que estamos complementando.', 1, '2026-09-12 15:47:29', NULL, NULL),
	(176, 18, 'ordenar_blocos', 'Ordene as instruções para verificar se um número digitado é Par ou Ímpar (usando resto da divisão):', 'Monte a lógica: Entrada -> Testar se resto é 0 -> Mensagem Par -> Senão -> Mensagem Ímpar.', 1, '2026-09-12 15:47:29', NULL, NULL),
	(177, 18, 'multipla_escolha', 'Quantos blocos de código (`Entao` ou `Senao`) podem ser executados ao mesmo tempo em um `Se-Entao-Senao`?', 'As opções são mutuamente exclusivas: ou o caminho verdadeiro é executado, ou o falso.', 1, '2026-09-12 15:47:29', NULL, NULL),
	(178, 18, 'completar_lacunas', 'Em um algoritmo com `Se-Entao-Senao`, a cláusula de fechamento `_______` deve ficar obrigatoriamente após o bloco do Senão.', 'Comando que sinaliza ao compilador o término da estrutura condicional.', 1, '2026-09-12 15:47:29', NULL, NULL),
	(179, 18, 'ordenar_blocos', 'Ordene a validação de acesso onde a senha correta é "1234":', 'Monte o fluxo: Leitura -> Teste de Senha -> Acesso Permitido -> Senão -> Acesso Negado -> FimSe.', 1, '2026-09-12 15:47:29', NULL, NULL),
	(180, 18, 'multipla_escolha', 'Qual dos seguintes trechos apresenta um erro de sintaxe na estrutura composta?', 'Observe a ordem correta das palavras reservadas na estrutura.', 1, '2026-09-12 15:47:29', NULL, NULL),
	(181, 19, 'multipla_escolha', 'Para que a expressão inteira com o operador lógico `E` seja Verdadeira, o que precisa acontecer com as condições testadas?', 'O operador E é exigente: necessita que todas as partes sejam simultaneamente verdadeiras.', 1, '2026-09-12 15:49:10', NULL, NULL),
	(182, 19, 'completar_lacunas', 'O operador lógico _______ exige que apenas UMA das condições seja verdadeira para que o resultado final seja Verdadeiro.', 'Operador de alternância ou flexibilidade lógica.', 1, '2026-09-12 15:49:10', NULL, NULL),
	(183, 19, 'ordenar_blocos', 'Ordene o algoritmo para verificar se um candidato atende aos dois requisitos de uma vaga (idade >= 18 E CNH = Verdadeiro):', 'Monte o fluxo: Entrada de dados -> Teste composto com E -> Mensagem de Aprovação -> Senao -> FimSe.', 1, '2026-09-12 15:49:10', NULL, NULL),
	(184, 19, 'multipla_escolha', 'Se tivermos a expressão `(idade >= 60 OU estudante = Verdadeiro)` e o usuário tiver 20 anos mas for estudante, qual será o resultado?', 'O operador OU retorna Verdadeiro se pelo menos uma das condições for satisfeita.', 1, '2026-09-12 15:49:10', NULL, NULL),
	(185, 19, 'completar_lacunas', 'O operador lógico de negação `_______` inverte o valor lógico de uma expressão (transforma Verdadeiro em Falso e vice-versa).', 'Operador de inversão lógica.', 1, '2026-09-12 15:49:10', NULL, NULL),
	(186, 19, 'ordenar_blocos', 'Ordene o algoritmo para conceder desconto de frete se o valor for maior que R$ 100 OU se o cliente tiver cupom VIP:', 'Estruture a lógica: Leitura -> Teste condicional com OU -> Aplicação do frete grátis -> FimSe.', 1, '2026-09-12 15:49:10', NULL, NULL),
	(187, 19, 'multipla_escolha', 'Qual será o resultado da expressão lógica `NAO (10 > 5)`?', 'Analise primeiro o teste interno (10 > 5) e depois aplique a negação do operador NAO.', 1, '2026-09-12 15:49:10', NULL, NULL),
	(188, 19, 'completar_lacunas', 'A combinação de condições usando operadores lógicos reduz a necessidade de criar vários comandos `Se` _______ (um dentro do outro).', 'Aninhados ou encadeados.', 1, '2026-09-12 15:49:10', NULL, NULL),
	(189, 19, 'ordenar_blocos', 'Ordene as instruções para verificar se um número está no intervalo entre 10 e 20 (inclusive):', 'Construa a validação: Leitura -> Condição (num >= 10 E num <= 20) -> Resposta -> FimSe.', 1, '2026-09-12 15:49:10', NULL, NULL),
	(190, 19, 'multipla_escolha', 'Qual das opções abaixo valida corretamente se uma pessoa pode votar (idade entre 16 e 70 anos)?', 'Para checar intervalos numéricos com limites inferior e superior, usa-se o operador E.', 1, '2026-09-12 15:49:10', NULL, NULL),
	(191, 20, 'multipla_escolha', 'Ao construir um algoritmo completo para um sistema de vendas, qual deve ser a ordem lógica padrão do fluxo de processamento de dados?', 'Considere o fluxo fundamental: entrada de dados, cálculos e tomada de decisão, e exibição dos resultados.', 1, '2026-09-12 15:49:49', NULL, NULL),
	(192, 20, 'completar_lacunas', 'A integração de variáveis, operadores e condicionais em um único bloco de código forma um algoritmo _______ completo.', 'Termo que indica um algoritmo organizado e bem definido.', 1, '2026-09-12 15:49:49', NULL, NULL),
	(193, 20, 'ordenar_blocos', 'Ordene o algoritmo completo de um sistema de aprovação escolar com verificação de frequência e média:', 'Siga o fluxo: Início -> Entrada de notas e frequência -> Cálculo da média -> Teste condicional composto -> Saída de dados -> Fim.', 1, '2026-09-12 15:49:49', NULL, NULL),
	(194, 20, 'multipla_escolha', 'No projeto final do módulo, o programa lê o valor de uma compra e a idade do cliente. Se a idade for >= 60 E o valor > 100, concede 20% de desconto. Caso contrário, não há desconto. Qual instrução implementa corretamente essa regra?', 'Combine as duas condições com o operador E.', 1, '2026-09-12 15:49:49', NULL, NULL),
	(195, 20, 'completar_lacunas', 'O teste de mesa é a técnica manual usada para acompanhar passo a passo o valor de cada _______ durante a execução do algoritmo.', 'Local de memória cujo conteúdo se altera no decorrer do programa.', 1, '2026-09-12 15:49:49', NULL, NULL),
	(196, 20, 'ordenar_blocos', 'Ordene as etapas de desenvolvimento de um sistema simples de caixa eletrônico para validação de saque:', 'Monte na sequência: Solicitar valor -> Verificar se há saldo suficiente -> Atualizar saldo e emitir mensagem -> Senão avisar erro.', 1, '2026-09-12 15:49:49', NULL, NULL),
	(197, 20, 'multipla_escolha', 'Ao final do Módulo 2, qual é a vantagem de dominar o pseudocódigo antes de migrar para uma linguagem como Python ou C++?', 'O pseudocódigo constrói o raciocínio estruturado sem o peso de regras sintáticas rigorosas.', 1, '2026-09-12 15:49:49', NULL, NULL),
	(198, 20, 'completar_lacunas', 'A clareza na escrita de um algoritmo estruturado evita ambiguidades e reduz erros de _______ durante o desenvolvimento.', 'Falhas na lógica de resolução do problema.', 1, '2026-09-12 15:49:49', NULL, NULL),
	(199, 20, 'ordenar_blocos', 'Ordene os blocos de um algoritmo que calcula a média de 3 números e informa se o valor resultante é Par ou Ímpar:', 'Pense na sequência: Leitura das 3 notas -> Cálculo da média -> Teste condicional de resto da divisão -> Exibição -> Fim.', 1, '2026-09-12 15:49:49', NULL, NULL),
	(200, 20, 'multipla_escolha', 'Qual dos conceitos aprendidos no Módulo 2 é responsável por permitir que o programa siga caminhos diferentes de acordo com as entradas do usuário?', 'Estruturas que realizam testes lógicos e alteram o fluxo.', 1, '2026-09-12 15:49:49', NULL, NULL),
	(201, 21, 'multipla_escolha', 'Qual é a característica fundamental da estrutura de repetição `Enquanto`?', 'Pense em quando a condição de parada é avaliada durante a execução do laço.', 1, '2026-09-24 19:41:52', NULL, NULL),
	(202, 21, 'completar_lacunas', 'O processo de alterar o valor de uma variável contadora a cada iteração para evitar um laço infinito é chamado de _______.', 'Termo usado para o incremento ou alteração da variável de controle.', 1, '2026-09-24 19:41:52', NULL, NULL),
	(203, 21, 'ordenar_blocos', 'Ordene o código em pseudocódigo que exibe os números de 1 a 5 usando o laço Enquanto:', 'Organize: Inicialização -> Teste condicional do Enquanto -> Ação -> Incremento -> FimEnquanto.', 1, '2026-09-24 19:41:52', NULL, NULL),
	(204, 21, 'multipla_escolha', 'O que acontece se a condição de um laço `Enquanto` for Falsa logo na primeira avaliação?', 'Se o teste inicial falha, o fluxo não entra no bloco de repetição.', 1, '2026-09-24 19:41:52', NULL, NULL),
	(205, 21, 'completar_lacunas', 'Quando um laço de repetição nunca atinge sua condição de parada, dizemos que o programa entrou em um loop _______.', 'Termo técnico para repetição sem fim.', 1, '2026-09-24 19:41:52', NULL, NULL),
	(206, 21, 'ordenar_blocos', 'Ordene os blocos de código para calcular a soma de 3 números inseridos pelo usuário:', 'Monte o fluxo completo: Inicializações -> Laço com leitura e acúmulo -> Incremento -> Exibição do resultado.', 1, '2026-09-24 19:41:52', NULL, NULL),
	(207, 21, 'multipla_escolha', 'O que faz a instrução `contador <- contador + 1` dentro de um laço de repetição?', 'Analise a atualização do valor anterior da variável somando uma unidade.', 1, '2026-09-24 19:41:52', NULL, NULL),
	(208, 21, 'ordenar_blocos', 'Ordene o algoritmo que solicita a senha do usuário até que ele digite a senha correta ("1234"):', 'Monte a estrutura: Leitura inicial -> Condição Enquanto incorreta -> Mensagem de erro e nova leitura -> FimEnquanto.', 1, '2026-09-24 19:41:52', NULL, NULL),
	(209, 21, 'completar_lacunas', 'A palavra reservada que sinaliza o encerramento do bloco de instruções do laço Enquanto é o _______.', 'Comando de fechamento da estrutura Enquanto.', 1, '2026-09-24 19:41:52', NULL, NULL),
	(210, 21, 'ordenar_blocos', 'Ordene o algoritmo que exibe uma contagem regressiva de 5 até 1:', 'Organize: Contador em 5 -> Enquanto maior que 0 -> Imprimir -> Decrementador (contador - 1) -> FimEnquanto.', 1, '2026-09-24 19:41:52', NULL, NULL),
	(211, 21, 'ordenar_blocos', 'Ordene o código para ler 5 valores e contar quantos são negativos:', 'Monte: Variáveis zeradas -> Enquanto (contador <= 5) -> Leitura -> Teste Se (menor que 0) -> Incrementar -> FimEnquanto.', 1, '2026-09-24 19:41:52', NULL, NULL),
	(212, 21, 'multipla_escolha', 'Analise o trecho: `c <- 1; Enquanto (c <= 3) Faca Escreva(c) FimEnquanto`. O que ocorrerá na execução?', 'Observe se a variável `c` está sendo modificada dentro do laço.', 1, '2026-09-24 19:41:52', NULL, NULL),
	(213, 22, 'multipla_escolha', 'Qual é a principal diferença entre a estrutura `Enquanto` e a estrutura `Faca-Enquanto` (ou `Repita-Ate`)?', 'Pense em quantas vezes o bloco interno é executado garantidamente antes da checagem da condição.', 1, '2026-09-24 19:46:00', NULL, NULL),
	(214, 22, 'completar_lacunas', 'A estrutura `Faca-Enquanto` garante que o bloco de instruções seja executado no mínimo _______ vez(es).', 'Número mínimo de execuções antes do primeiro teste lógico.', 1, '2026-09-24 19:46:00', NULL, NULL),
	(215, 22, 'ordenar_blocos', 'Ordene os blocos para criar um menu interativo simples que repete até o usuário digitar a opção 0:', 'Monte a lógica: Faca -> Mostrar opções e ler escolha -> Teste Enquanto (opcao <> 0) no final.', 1, '2026-09-24 19:46:00', NULL, NULL),
	(216, 22, 'multipla_escolha', 'Em quais cenários práticos o laço `Faca-Enquanto` é mais recomendado que o `Enquanto` simples?', 'Pense em situações onde a primeira leitura ou ação precisa ocorrer antes de validar se continua.', 1, '2026-09-24 19:46:00', NULL, NULL),
	(217, 22, 'completar_lacunas', 'No laço `Repita-Ate`, a repetição é mantida enquanto a condição for Falsa e é encerrada assim que a condição se torna _______.', 'Resultado lógico que encerra a repetição no Repita-Até.', 1, '2026-09-24 19:46:00', NULL, NULL),
	(218, 22, 'ordenar_blocos', 'Ordene o algoritmo para validar a entrada de uma nota (deve estar obrigatoriamente entre 0 e 10):', 'Estruture: Faca -> Pedir nota e ler -> Enquanto a nota for inválida (< 0 OU > 10).', 1, '2026-09-24 19:46:00', NULL, NULL),
	(219, 22, 'ordenar_blocos', 'Ordene o código que soma números informados pelo usuário e para assim que um número negativo for digitado:', 'Siga: Zerar soma -> Faca -> Ler num e somar se positivo -> Enquanto (num >= 0).', 1, '2026-09-24 19:46:00', NULL, NULL),
	(220, 22, 'multipla_escolha', 'Se a condição de parada do `Faca-Enquanto` for Falsa já no primeiro teste, quantas vezes o bloco terá sido executado?', 'Lembre-se de que o teste ocorre apenas após a primeira passagem.', 1, '2026-09-24 19:46:00', NULL, NULL),
	(221, 22, 'completar_lacunas', 'Na instrução `Faca ... Enquanto (condicao)`, a avaliação da expressão lógica ocorre na parte _______ do laço.', 'Posição onde o teste condicional é aplicado.', 1, '2026-09-24 19:46:00', NULL, NULL),
	(222, 22, 'ordenar_blocos', 'Ordene o código para exibir os números de 1 a 3 utilizando a estrutura Faca-Enquanto:', 'Organize: Inicializar c <- 1 -> Faca -> Escrever c -> Incrementar c -> Enquanto (c <= 3).', 1, '2026-09-24 19:46:00', NULL, NULL),
	(223, 22, 'ordenar_blocos', 'Ordene o programa que obriga a digitação de uma confirmação "S" ou "N":', 'Monte: Faca -> Pedir resposta -> Ler opcao -> Enquanto (opcao <> "S" E opcao <> "N").', 1, '2026-09-24 19:46:00', NULL, NULL),
	(224, 22, 'multipla_escolha', 'O que acontece no trecho: `c <- 10; Faca Escreva(c); c <- c + 1 Enquanto (c < 5)`?', 'Analise a execução do bloco e a condição ao final.', 1, '2026-09-24 19:46:00', NULL, NULL),
	(225, 23, 'multipla_escolha', 'Qual é a principal indicação para o uso do laço `Para` em comparação ao `Enquanto`?', 'Pense em situações em que você já sabe exatamente quantas repetições precisa realizar antes de iniciar.', 1, '2026-09-24 20:08:30', NULL, NULL),
	(226, 23, 'completar_lacunas', 'No laço `Para`, a atualização da variável contadora ocorre de forma _______ a cada iteração executada.', 'O próprio laço gerencia a progressão do valor da variável de controle.', 1, '2026-09-24 20:08:30', NULL, NULL),
	(227, 23, 'ordenar_blocos', 'Ordene o algoritmo em pseudocódigo que exibe os números pares de 2 até 10 usando o laço Para:', 'Siga a estrutura: Para i de 2 ate 10 passo 2 -> Escreva(i) -> FimPara.', 1, '2026-09-24 20:08:30', NULL, NULL),
	(228, 23, 'multipla_escolha', 'Na instrução `Para i de 1 ate 5 Faca`, quantas vezes o bloco de código interno será executado?', 'Conte os valores do intervalo inclusivo de 1 a 5.', 1, '2026-09-24 20:08:30', NULL, NULL),
	(229, 23, 'completar_lacunas', 'Para realizar uma contagem regressiva no laço Para, utilizamos a palavra reservada `passo` acompanhada de um número _______.', 'Sinal do valor numérico necessário para diminuir o contador.', 1, '2026-09-24 20:08:30', NULL, NULL),
	(230, 23, 'ordenar_blocos', 'Ordene os blocos para calcular e exibir a tabuada do 7 (de 1 a 10) usando o laço Para:', 'Monte: Inicializar numero <- 7 -> Para i de 1 ate 10 -> Escrever produto -> FimPara.', 1, '2026-09-24 20:08:30', NULL, NULL),
	(231, 23, 'ordenar_blocos', 'Ordene o algoritmo para somar 5 números inteiros inseridos pelo usuário:', 'Monte: soma <- 0 -> Para i de 1 ate 5 -> Ler num -> soma <- soma + num -> FimPara.', 1, '2026-09-24 20:08:30', NULL, NULL),
	(232, 23, 'multipla_escolha', 'O que acontece se omitirmos a cláusula `passo` em um laço `Para i de 1 ate 10 Faca`?', 'Por padrão, qual é a variação automática aplicada à variável contadora?', 1, '2026-09-24 20:08:30', NULL, NULL),
	(233, 23, 'completar_lacunas', 'A palavra reservada que sinaliza o fechamento da estrutura contada é o _______.', 'Comando de finalização do bloco Para.', 1, '2026-09-24 20:08:30', NULL, NULL),
	(234, 23, 'ordenar_blocos', 'Ordene os blocos para realizar uma contagem regressiva de 10 até 1 com decremente de 1:', 'Organize: Para i de 10 ate 1 passo -1 -> Escreva(i) -> FimPara -> Escreva("FIM").', 1, '2026-09-24 20:08:30', NULL, NULL),
	(235, 23, 'ordenar_blocos', 'Ordene o código para ler a idade de 4 pessoas e contar quantas são maiores de idade:', 'Monte: maiores <- 0 -> Para i de 1 ate 4 -> Ler idade -> Se (idade >= 18) -> FimPara.', 1, '2026-09-24 20:08:30', NULL, NULL),
	(236, 23, 'multipla_escolha', 'Analise o trecho: `Para i de 5 ate 1 Faca Escreva(i) FimPara`. Qual será a saída do programa?', 'Note que o valor inicial é maior que o final e não foi especificado um passo negativo.', 1, '2026-09-24 20:08:30', NULL, NULL),
	(237, 24, 'multipla_escolha', 'Em uma estrutura com laços aninhados (um laço dentro do outro), quantas vezes o laço interno executa completamente?', 'Para cada única iteração do laço externo, o laço interno realiza todas as suas iterações.', 1, '2026-09-24 20:09:44', NULL, NULL),
	(238, 24, 'completar_lacunas', 'Em laços aninhados, cada repetição do laço externo força a execução _______ do laço interno.', 'Total/completa do laço interno.', 1, '2026-09-24 20:09:44', NULL, NULL),
	(239, 24, 'ordenar_blocos', 'Ordene o código para imprimir uma matriz quadrada simples 2x2 com asteriscos utilizando laços Para aninhados:', 'Monte a estrutura: Para i (linhas) -> Para j (colunas) -> Imprimir "*" -> FimPara j -> Nova linha -> FimPara i.', 1, '2026-09-24 20:09:44', NULL, NULL),
	(240, 24, 'multipla_escolha', 'Se o laço externo executa 3 vezes e o laço interno executa 4 vezes a cada rodada, quantas vezes o bloco interno será processado no total?', 'Multiplique o número de iterações externas pelas internas (3 * 4).', 1, '2026-09-24 20:09:44', NULL, NULL),
	(241, 24, 'completar_lacunas', 'É fundamental utilizar variáveis de controle _______ para o laço externo e para o laço interno para evitar conflitos de contagem.', 'Diferentes/distintas (ex: i e j).', 1, '2026-09-24 20:09:44', NULL, NULL),
	(242, 24, 'ordenar_blocos', 'Ordene os blocos para gerar as tabuadas completas do 1 ao 3 utilizando laços aninhados:', 'Estruture: Para i (1 a 3) -> Para j (1 a 10) -> Imprimir produto -> FimPara j -> FimPara i.', 1, '2026-09-24 20:09:44', NULL, NULL),
	(243, 24, 'ordenar_blocos', 'Ordene o algoritmo para ler as notas de 3 alunos, onde cada aluno possui 2 notas:', 'Monte: Para aluno de 1 ate 3 -> Para nota de 1 ate 2 -> Ler nota -> FimPara nota -> FimPara aluno.', 1, '2026-09-24 20:09:44', NULL, NULL),
	(244, 24, 'multipla_escolha', 'Qual é o principal cuidado ao utilizar múltiplos laços aninhados em programas com grandes volumes de dados?', 'Considere o aumento exponencial no número total de iterações e no tempo de processamento.', 1, '2026-09-24 20:09:44', NULL, NULL),
	(245, 24, 'completar_lacunas', 'O fechamento dos laços aninhados deve seguir a ordem inversa da abertura: o laço interno deve ter seu `FimPara` posicionado _______ do `FimPara` do laço externo.', 'Posição relativa do fechamento interno em relação ao externo.', 1, '2026-09-24 20:09:44', NULL, NULL),
	(246, 24, 'ordenar_blocos', 'Ordene os blocos para contar quantas combinações de dados existem entre 2 turnos e 3 turmas:', 'Organize: Para t de 1 ate 2 -> Para c de 1 ate 3 -> Incrementar contador -> FimPara c -> FimPara t.', 1, '2026-09-24 20:09:44', NULL, NULL),
	(247, 25, 'multipla_escolha', 'O que é um vetor (array unidimensional) na programação?', 'Pense em uma sequência de caixas na memória identificadas por um único nome e acessadas por posição.', 1, '2026-09-24 20:09:44', NULL, NULL),
	(248, 25, 'completar_lacunas', 'A posição de um elemento específico dentro de um vetor é identificada através do seu _______.', 'Termo usado para definir o número do índice do elemento.', 1, '2026-09-24 20:09:44', NULL, NULL),
	(249, 25, 'ordenar_blocos', 'Ordene o código para declarar um vetor de 5 números inteiros e preenchê-lo via teclado:', 'Siga o fluxo: Declarar vetor -> Laço Para (1 a 5) -> Leitura no elemento vetor[i] -> FimPara.', 1, '2026-09-24 20:09:44', NULL, NULL),
	(250, 25, 'multipla_escolha', 'Se declararmos um vetor `notas` com 4 posições (`notas[1..4]`), o que ocorre ao tentar acessar `notas[5]`?', 'Acessar uma posição fora do intervalo reservado gera uma falha de limites.', 1, '2026-09-24 20:09:44', NULL, NULL),
	(251, 25, 'completar_lacunas', 'Um vetor é considerado uma estrutura de dados _______ porque armazena apenas elementos do mesmo tipo de dado.', 'Propriedade de guardar dados de um único tipo.', 1, '2026-09-24 20:09:44', NULL, NULL),
	(252, 25, 'ordenar_blocos', 'Ordene o algoritmo para exibir na tela todos os valores armazenados em um vetor de 4 posições:', 'Monte: Inicializar vetor preenchido -> Laço Para (1 a 4) -> Escrever vetor[i] -> FimPara.', 1, '2026-09-24 20:09:44', NULL, NULL),
	(253, 25, 'ordenar_blocos', 'Ordene as instruções para calcular a soma de todos os 5 elementos de um vetor já preenchido:', 'Estruture: soma <- 0 -> Para i de 1 ate 5 -> soma <- soma + vetor[i] -> FimPara -> Exibir soma.', 1, '2026-09-24 20:09:44', NULL, NULL),
	(254, 25, 'multipla_escolha', 'Qual é a principal vantagem de usar um vetor para armazenar 10 notas em vez de criar 10 variáveis simples (`n1`, `n2`, ..., `n10`)?', 'Considere a facilidade de percorrer todos os dados usando um laço de repetição.', 1, '2026-09-24 20:09:44', NULL, NULL),
	(255, 25, 'completar_lacunas', 'Para acessar ou alterar o terceiro elemento de um vetor chamado `valores`, escrevemos `valores[_______]`.', 'Número da posição do elemento.', 1, '2026-09-24 20:09:44', NULL, NULL),
	(256, 25, 'ordenar_blocos', 'Ordene o código para contar quantos números pares estão armazenados em um vetor de 5 posições:', 'Organize: pares <- 0 -> Para i de 1 ate 5 -> Se (vetor[i] % 2 = 0) pares <- pares + 1 -> FimPara.', 1, '2026-09-24 20:09:44', NULL, NULL),
	(257, 25, 'ordenar_blocos', 'Ordene o algoritmo para dobrar o valor guardado em cada posição de um vetor de 3 elementos:', 'Monte: Para i de 1 ate 3 -> vetor[i] <- vetor[i] * 2 -> FimPara -> Imprimir confirmação.', 1, '2026-09-24 20:09:44', NULL, NULL),
	(258, 25, 'completar_lacunas', 'A combinação da estrutura de repetição `_______` com vetores é o padrão mais comum para percorrer todas as posições de forma automatizada.', 'Laço de repetição com número de iterações determinado.', 1, '2026-09-24 20:09:44', NULL, NULL),
	(259, 25, 'multipla_escolha', 'Dado o vetor `idades = [12, 25, 18]`, qual valor está armazenado em `idades[2]`?', 'Identifique o elemento na segunda posição do vetor.', 1, '2026-09-24 20:09:44', NULL, NULL),
	(260, 26, 'multipla_escolha', 'Ao buscar o MAIOR valor em um vetor, com qual elemento a variável `maior` deve ser inicializada preferencialmente?', 'Pense em usar um valor do próprio vetor para evitar problemas com números negativos.', 1, '2026-09-24 20:10:36', NULL, NULL),
	(261, 26, 'completar_lacunas', 'O algoritmo de busca sequencial percorre o vetor do primeiro ao último elemento comparando o valor procurado com a posição _______.', 'Forma de acessar o elemento atual no laço (vetor[i]).', 1, '2026-09-24 20:10:36', NULL, NULL),
	(262, 26, 'ordenar_blocos', 'Ordene o algoritmo para encontrar e exibir o maior número em um vetor de 5 posições:', 'Monte: maior <- v[1] -> Para i de 2 ate 5 -> Se (v[i] > maior) Entao maior <- v[i] FimSe -> FimPara -> Escrever maior.', 1, '2026-09-24 20:10:36', NULL, NULL),
	(263, 26, 'multipla_escolha', 'Qual é a utilidade de uma variável do tipo `Lógico` (flag/bandeira) durante uma busca em um vetor?', 'Considere como sinalizar que o elemento foi encontrado antes de concluir a varredura.', 1, '2026-09-24 20:10:36', NULL, NULL),
	(264, 26, 'completar_lacunas', 'Para calcular a média dos elementos de um vetor de N posições, dividimos o acumulador total pelo valor de _______.', 'Quantidade total de elementos do vetor.', 1, '2026-09-24 20:10:36', NULL, NULL),
	(265, 26, 'ordenar_blocos', 'Ordene o código para realizar uma busca sequencial de um número informado pelo usuário em um vetor de 4 elementos:', 'Estruture: Ler num -> enc <- falso -> Para i de 1 ate 4 -> Se (v[i] = num) enc <- verdadeiro -> FimPara.', 1, '2026-09-24 20:10:36', NULL, NULL),
	(266, 26, 'ordenar_blocos', 'Ordene os blocos para calcular a média de 4 notas salvas no vetor `notas` e exibir o resultado:', 'Monte: soma <- 0 -> Para i de 1 ate 4 -> soma <- soma + notas[i] -> FimPara -> media <- soma / 4.', 1, '2026-09-24 20:10:36', NULL, NULL),
	(267, 26, 'multipla_escolha', 'O que ocorre se inicializarmos a variável `menor` com o valor `0` para buscar o menor número em um vetor com os valores `[10, 5, 8, 3]`?', 'Analise se algum número do vetor é menor que 0.', 1, '2026-09-24 20:10:36', NULL, NULL),
	(268, 26, 'completar_lacunas', 'A técnica de verificar item por item de um vetor a partir do índice 1 até o final é chamada de busca _______.', 'Tipo de busca elementar realizada item a item.', 1, '2026-09-24 20:10:36', NULL, NULL),
	(269, 26, 'ordenar_blocos', 'Ordene o algoritmo para contar quantos valores em um vetor de 5 elementos são maiores que a média de 6.0:', 'Organize: qtd <- 0 -> Para i de 1 ate 5 -> Se (v[i] > 6.0) Entao qtd <- qtd + 1 FimSe -> FimPara.', 1, '2026-09-24 20:10:36', NULL, NULL),
	(270, 26, 'ordenar_blocos', 'Ordene os blocos para encontrar o menor valor armazenado em um vetor de 5 números:', 'Monte: menor <- v[1] -> Para i de 2 ate 5 -> Se (v[i] < menor) Entao menor <- v[i] FimSe -> FimPara.', 1, '2026-09-24 20:10:36', NULL, NULL),
	(271, 26, 'completar_lacunas', 'Em um algoritmo de acúmulo em vetor, a variável responsável por somar os valores deve ser inicializada com o valor _______.', 'Elemento neutro da soma.', 1, '2026-09-24 20:10:36', NULL, NULL),
	(272, 26, 'multipla_escolha', 'Quantas comparações, no pior caso, uma busca sequencial realiza em um vetor com 100 elementos?', 'Pense no cenário onde o item está na última posição ou não existe.', 1, '2026-09-24 20:10:36', NULL, NULL),
	(273, 27, 'multipla_escolha', 'O que caracteriza uma matriz (array bidimensional) em relação a um vetor simples?', 'Pense na organização em formato de tabela, possuindo duas dimensões: linhas e colunas.', 1, '2026-09-24 20:10:37', NULL, NULL),
	(274, 27, 'completar_lacunas', 'Para identificar um elemento individual em uma matriz bidimensional, precisamos informar dois índices: a _______ e a coluna.', 'Dimensão vertical da matriz acessada pelo primeiro índice.', 1, '2026-09-24 20:10:37', NULL, NULL),
	(275, 27, 'ordenar_blocos', 'Ordene o código para declarar uma matriz 2x2 e preenchê-la com dados via teclado:', 'Estruture: Declarar matriz -> Para i (1 a 2) -> Para j (1 a 2) -> Ler m[i,j] -> FimPara j -> FimPara i.', 1, '2026-09-24 20:10:37', NULL, NULL),
	(276, 27, 'multipla_escolha', 'Quantas posições no total existem em uma matriz declarada com 3 linhas e 4 colunas (`m[1..3, 1..4]`)?', 'Multiplique o número de linhas pelo número de colunas (3 * 4).', 1, '2026-09-24 20:10:37', NULL, NULL),
	(277, 27, 'completar_lacunas', 'Para percorrer completamente uma matriz bidimensional de forma automatizada, utilizamos dois laços de repetição _______.', 'Termo para estruturas de repetição colocadas uma dentro da outra.', 1, '2026-09-24 20:10:37', NULL, NULL),
	(278, 27, 'ordenar_blocos', 'Ordene os blocos de código para imprimir o conteúdo de uma matriz 2x2 no formato de grade:', 'Monte: Para i de 1 ate 2 -> Para j de 1 ate 2 -> Imprimir m[i,j] -> FimPara j -> Imprimir quebra de linha -> FimPara i.', 1, '2026-09-24 20:10:37', NULL, NULL),
	(279, 27, 'ordenar_blocos', 'Ordene o algoritmo para somar todos os elementos de uma matriz 2x2 preenchida:', 'Estruture: soma <- 0 -> Para i de 1 ate 2 -> Para j de 1 ate 2 -> soma <- soma + m[i,j] -> FimPara j -> FimPara i.', 1, '2026-09-24 20:10:37', NULL, NULL),
	(280, 27, 'multipla_escolha', 'Na sintaxe `matriz[2, 3]`, o que os números `2` e `3` representam respectivamente?', 'Considere a convenção padrão de indexação: primeiro parâmetro e segundo parâmetro.', 1, '2026-09-24 20:10:37', NULL, NULL),
	(281, 27, 'completar_lacunas', 'Uma matriz quadrada é aquela que possui a quantidade de linhas _______ à quantidade de colunas.', 'Relação de igualdade entre as dimensões.', 1, '2026-09-24 20:10:37', NULL, NULL),
	(282, 27, 'ordenar_blocos', 'Ordene os blocos para zerar (atribuir 0 a) todos os elementos de uma matriz 2x3:', 'Organize: Para i de 1 ate 2 -> Para j de 1 ate 3 -> m[i,j] <- 0 -> FimPara j -> FimPara i.', 1, '2026-09-24 20:10:37', NULL, NULL),
	(283, 28, 'multipla_escolha', 'Em uma matriz quadrada, qual condição matemática identifica os elementos pertencentes à Diagonal Principal?', 'Observe a relação entre o índice da linha (i) e o índice da coluna (j).', 1, '2026-09-24 20:12:19', NULL, NULL),
	(284, 28, 'completar_lacunas', 'Os elementos da diagonal principal de uma matriz quadrada possuem o índice da linha igual ao índice da _______.', 'Termo correspondente ao segundo subsobrescrito [i, j].', 1, '2026-09-24 20:12:19', NULL, NULL),
	(285, 28, 'ordenar_blocos', 'Ordene os blocos para exibir apenas os elementos da diagonal principal de uma matriz 3x3:', 'Monte: Para i de 1 ate 3 -> Escreva(mat[i, i]) -> FimPara.', 1, '2026-09-24 20:12:19', NULL, NULL),
	(286, 28, 'multipla_escolha', 'Para calcular a soma dos elementos de uma linha específica L em uma matriz M, qual laço de repetição devemos utilizar?', 'A linha L permanece fixa enquanto iteramos sobre todas as colunas.', 1, '2026-09-24 20:12:19', NULL, NULL),
	(287, 28, 'completar_lacunas', 'Para somar os elementos da primeira coluna de uma matriz, mantemos o índice da coluna fixo em 1 e variamos o índice da _______.', 'Dimensão vertical que varia para percorrer a coluna.', 1, '2026-09-24 20:12:19', NULL, NULL),
	(288, 28, 'ordenar_blocos', 'Ordene o algoritmo para somar todos os elementos da diagonal principal de uma matriz 3x3:', 'Estruture: soma <- 0 -> Para i de 1 ate 3 -> soma <- soma + mat[i, i] -> FimPara -> Escrever soma.', 1, '2026-09-24 20:12:19', NULL, NULL),
	(289, 28, 'ordenar_blocos', 'Ordene o código para somar os valores contidos na linha 2 de uma matriz 3x3:', 'Monte: soma <- 0 -> Para j de 1 ate 3 -> soma <- soma + mat[2, j] -> FimPara -> Escrever soma.', 1, '2026-09-24 20:12:19', NULL, NULL),
	(290, 28, 'multipla_escolha', 'Em uma matriz 3x3, quais são os pares de índices [linha, coluna] que compõem a Diagonal Principal?', 'Lembre-se da regra i = j.', 1, '2026-09-24 20:12:19', NULL, NULL),
	(291, 28, 'completar_lacunas', 'A soma dos elementos de uma matriz onde linha é maior que coluna (i > j) corresponde aos elementos situados _______ da diagonal principal.', 'Posição dos elementos com i > j em relação à diagonal principal.', 1, '2026-09-24 20:12:19', NULL, NULL),
	(292, 28, 'ordenar_blocos', 'Ordene os blocos para verificar quantos elementos de uma matriz 2x2 são maiores que 10:', 'Organize: qtd <- 0 -> Para i de 1 ate 2 -> Para j de 1 ate 2 -> Se (mat[i,j] > 10) qtd <- qtd + 1 -> FimPara.', 1, '2026-09-24 20:12:19', NULL, NULL),
	(293, 29, 'multipla_escolha', 'Qual é a diferença essencial entre uma Função e um Procedimento na programação?', 'Pense na entrega de um valor processado de volta para quem chamou a sub-rotina.', 1, '2026-09-24 20:12:19', NULL, NULL),
	(294, 29, 'completar_lacunas', 'O comando utilizado dentro de uma função para enviar o valor calculado de volta ao programa principal é o _______.', 'Instrução de saída da função que devolve o resultado.', 1, '2026-09-24 20:12:19', NULL, NULL),
	(295, 29, 'ordenar_blocos', 'Ordene o código para criar um procedimento que exibe uma linha divisória na tela:', 'Siga: Procedimento Linha() -> Imprimir "--------------------" -> FimProcedimento -> Chamada Linha().', 1, '2026-09-24 20:12:19', NULL, NULL),
	(296, 29, 'multipla_escolha', 'Qual é a principal vantagem de modularizar um algoritmo em funções e procedimentos?', 'Considere o reúso de código, a organização e a facilidade de manutenção.', 1, '2026-09-24 20:12:19', NULL, NULL),
	(297, 29, 'completar_lacunas', 'As variáveis declaradas exclusivamente dentro de uma função ou procedimento são chamadas de variáveis _______.', 'Escopo restrito ao bloco onde foram criadas.', 1, '2026-09-24 20:12:19', NULL, NULL),
	(298, 29, 'ordenar_blocos', 'Ordene o código de uma função que recebe dois números e retorna a soma deles:', 'Monte: Funcao Somar(a, b) -> Retorne a + b -> FimFuncao -> res <- Somar(5, 3) -> Escrever res.', 1, '2026-09-24 20:12:19', NULL, NULL),
	(299, 29, 'ordenar_blocos', 'Ordene a chamada de um procedimento que recebe o nome de um usuário e exibe uma saudação personalizada:', 'Estruture: Procedimento Saudacao(nome) -> Escreva("Olá ", nome) -> FimProcedimento -> Saudacao("Carlos").', 1, '2026-09-24 20:12:19', NULL, NULL),
	(300, 29, 'multipla_escolha', 'O que são parâmetros em uma sub-rotina (função ou procedimento)?', 'Pense nas informações passadas como entrada para que o bloco execute seu trabalho.', 1, '2026-09-24 20:12:19', NULL, NULL),
	(301, 29, 'completar_lacunas', 'Variáveis declaradas no corpo principal do programa e acessíveis por qualquer bloco são chamadas de variáveis _______.', 'Escopo amplo e visível por todo o algoritmo.', 1, '2026-09-24 20:12:19', NULL, NULL),
	(302, 29, 'ordenar_blocos', 'Ordene os blocos de uma função que verifica se um número é Par (retorna Verdadeiro ou Falso):', 'Monte: Funcao EhPar(n) -> Se (n % 2 = 0) Retorne verdadeiro Senao Retorne falso -> FimFuncao.', 1, '2026-09-24 20:12:19', NULL, NULL),
	(303, 29, 'ordenar_blocos', 'Ordene os blocos para criar um procedimento de exibição de cabeçalho do sistema:', 'Organize: Procedimento Cabecalho() -> Escreva("=== SISTEMA V1.0 ===") -> FimProcedimento -> Cabecalho().', 1, '2026-09-24 20:12:19', NULL, NULL),
	(304, 29, 'completar_lacunas', 'A passagem de parâmetros onde a sub-rotina recebe uma cópia do valor original sem alterá-lo diretamente é a passagem por _______.', 'Forma padrão de envio de argumentos onde o valor original fica protegido.', 1, '2026-09-24 20:12:19', NULL, NULL),
	(305, 29, 'multipla_escolha', 'Ao tentar executar `x <- ImprimirMensagem("Teste")`, sabendo que `ImprimirMensagem` é um PROCEDIMENTO, o que ocorrerá?', 'Procedimentos não retornam valores para atribuição.', 1, '2026-09-24 20:12:19', NULL, NULL),
	(306, 30, 'multipla_escolha', 'No projeto integrador do módulo, qual combinação de estruturas é ideal para construir um sistema de gestão de estoque com menu interativo e cadastro de produtos?', 'Considere um laço para manter o menu ativo, vetores para guardar os produtos e funções para as operações.', 1, '2026-09-24 20:12:20', NULL, NULL),
	(307, 30, 'completar_lacunas', 'A integração de laços de repetição com vetores e procedimentos permite construir sistemas modulares e _______ de fácil manutenção.', 'Termo para código bem organizado, estruturado e escalável.', 1, '2026-09-24 20:12:20', NULL, NULL),
	(308, 30, 'ordenar_blocos', 'Ordene o projeto simplificado que lê 3 notas em um vetor usando laço Para e calcula a média via função:', 'Monte: Preencher vetor -> Chamar funcao CalcularMedia -> Receber resultado -> Imprimir media.', 1, '2026-09-24 20:12:20', NULL, NULL),
	(309, 30, 'multipla_escolha', 'Ao projetar um sistema que necessita armazenar a nota de 5 alunos em 3 disciplinas cada, qual é a estrutura de dados mais adequada?', 'Análise entre variável simples, vetor de 1D ou matriz 2D.', 1, '2026-09-24 20:12:20', NULL, NULL),
	(310, 30, 'completar_lacunas', 'O teste de mesa em sistemas com laços e vetores envolve acompanhar a evolução dos índices e os valores das posições a cada _______.', 'Termo para cada rodada ou repetição do laço.', 1, '2026-09-24 20:12:20', NULL, NULL),
	(311, 30, 'ordenar_blocos', 'Ordene os blocos de um programa completo com menu interativo usando Faca-Enquanto que chama um procedimento:', 'Organize: Faca -> Exibir menu e ler opcao -> Se opcao=1 chamar Processar() -> Enquanto opcao <> 0.', 1, '2026-09-24 20:12:20', NULL, NULL),
	(312, 30, 'ordenar_blocos', 'Ordene a lógica de um algoritmo que preenche um vetor de 4 posições e busca um elemento através de uma função:', 'Monte: Ler vetor -> Ler busca -> chamar Funcao Buscar(vetor, chave) -> Exibir se encontrou.', 1, '2026-09-24 20:12:20', NULL, NULL),
	(313, 30, 'multipla_escolha', 'Ao concluir o Módulo 3, qual das alternativas descreve a transição correta para linguagens de programação reais (como Python, C ou Java)?', 'A lógica estruturada, laços e vetores aprendidos continuam exatamente os mesmos, mudando apenas a sintaxe da linguagem.', 1, '2026-09-24 20:12:20', NULL, NULL),
	(314, 30, 'completar_lacunas', 'Subdividir um problema grande em pequenas funções específicas facilita o processo de _______ ao buscar e corrigir erros.', 'Prática de localizar e solucionar falhas no código (depuração/debugging).', 1, '2026-09-24 20:12:20', NULL, NULL),
	(315, 30, 'ordenar_blocos', 'Ordene os blocos de um sistema que calcula e exibe a média dos elementos de uma matriz 2x2:', 'Monte: soma <- 0 -> Para i e j (acumular soma) -> media <- soma / 4 -> Escrever media.', 1, '2026-09-24 20:12:20', NULL, NULL),
	(316, 30, 'ordenar_blocos', 'Ordene as etapas de um programa modular que utiliza procedimento para cadastrar valores em um vetor:', 'Organize: Declarar vetor -> Procedimento Cadastrar() -> Laço Para preenchendo -> Chamada Cadastrar().', 1, '2026-09-24 20:12:20', NULL, NULL),
	(317, 30, 'completar_lacunas', 'Em programas complexos, a reutilização de funções previne a redundância de código e reduz o risco de inconsistência na _______.', 'Construção da lógica de programação.', 1, '2026-09-24 20:12:20', NULL, NULL),
	(318, 30, 'multipla_escolha', 'Qual é o impacto principal de implementar modularização em projetos que trabalham com matrizes e vetores de grande porte?', 'Pense na clareza do fluxo principal e no isolamento de responsabilidades.', 1, '2026-09-24 20:12:20', NULL, NULL),
	(319, 31, 'multipla_escolha', 'Qual é a ideia central do algoritmo Bubble Sort para ordenar um vetor?', 'Pense em comparar elementos vizinhos e trocá-los se estiverem fora de ordem.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(320, 31, 'completar_lacunas', 'No Bubble Sort, a variável temporária utilizada para permitir a troca de valores entre duas posições sem perder dados é chamada de _______.', 'Variável usada como auxílio temporário na troca.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(321, 31, 'ordenar_blocos', 'Ordene o código que realiza a troca de valores entre vetor[i] e vetor[i+1] usando uma variável auxiliar:', 'Monte: aux <- v[i] -> v[i] <- v[i+1] -> v[i+1] <- aux.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(322, 31, 'multipla_escolha', 'Em um vetor com N elementos, quantas comparações no máximo o Bubble Sort realiza em sua primeira passagem?', 'Pense no número de pares adjacentes existentes (N - 1).', 1, '2026-09-24 20:48:59', NULL, NULL),
	(323, 31, 'completar_lacunas', 'O algoritmo Bubble Sort necessita de dois laços de repetição _______ para percorrer e ordenar todas as posições.', 'Laços um dentro do outro.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(324, 31, 'ordenar_blocos', 'Ordene os blocos para implementar a estrutura completa do Bubble Sort para um vetor de 4 posições:', 'Monte: Laço externo (i de 1 ate 3) -> Laço interno (j de 1 ate 3) -> Se (v[j] > v[j+1]) efetuar troca.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(325, 31, 'ordenar_blocos', 'Ordene os blocos para ordenar um vetor em ordem DECRESCENTE usando o teste de comparação correto:', 'Monte: Para i -> Para j -> Se (v[j] < v[j+1]) -> Trocar valores -> FimPara.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(326, 31, 'multipla_escolha', 'O que acontece com o MAIOR elemento do vetor após a primeira passagem completa do laço interno no Bubble Sort crescente?', 'Ele "flutua" até a sua posição correta no final do vetor.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(327, 31, 'completar_lacunas', 'Para ordenar um vetor em ordem crescente, realizamos a troca quando o elemento atual for _______ que o elemento seguinte.', 'Relação de comparação entre v[j] e v[j+1].', 1, '2026-09-24 20:48:59', NULL, NULL),
	(328, 31, 'ordenar_blocos', 'Ordene a rotina de impressão de um vetor de 4 posições após ser totalmente ordenado:', 'Organize: Escreva("Vetor Ordenado:") -> Para i de 1 ate 4 -> Escreva(v[i]) -> FimPara.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(329, 31, 'ordenar_blocos', 'Ordene o teste condicional que verifica se dois elementos vizinhos precisam ser trocados em ordem crescente:', 'Siga: Se (v[j] > v[j+1]) Entao -> aux <- v[j] -> v[j] <- v[j+1] -> v[j+1] <- aux -> FimSe.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(330, 31, 'multipla_escolha', 'Qual é a complexidade de tempo no pior caso do algoritmo Bubble Sort para N elementos?', 'Considere dois laços aninhados executando aproximadamente N vezes cada.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(331, 31, 'multipla_escolha', 'Qual é o princípio de funcionamento do algoritmo Selection Sort?', 'Identificar o menor elemento restante e movê-lo para a posição inicial correspondente.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(332, 32, 'completar_lacunas', 'Diferente do Bubble Sort que realiza várias trocas por passagem, o Selection Sort realiza no máximo _______ troca(s) por iteração do laço externo.', 'Quantidade de trocas diretas executadas ao fim de cada varredura.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(333, 32, 'ordenar_blocos', 'Ordene os blocos para encontrar o menor elemento a partir do índice `i` no Selection Sort:', 'Monte: min <- i -> Para j de i+1 ate N -> Se (v[j] < v[min]) min <- j -> FimPara.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(334, 32, 'multipla_escolha', 'Em qual situação o Selection Sort leva vantagem em relação ao Bubble Sort tradicional?', 'Pense na quantidade total de operações de escrita/troca na memória.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(335, 32, 'completar_lacunas', 'No Selection Sort, a variável `min` guarda o _______ do elemento com o menor valor encontrado.', 'Termo para a posição/índice do menor valor.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(336, 32, 'ordenar_blocos', 'Ordene o trecho final de troca do Selection Sort após localizar o índice do menor elemento:', 'Monte: Se (min <> i) Entao -> aux <- v[i] -> v[i] <- v[min] -> v[min] <- aux -> FimSe.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(337, 32, 'ordenar_blocos', 'Ordene os blocos principais do algoritmo Selection Sort para um vetor de 5 posições:', 'Monte: Para i de 1 ate 4 -> min <- i -> Para j de i+1 ate 5 -> Se (v[j]<v[min]) min <- j -> FimPara -> Trocar.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(338, 32, 'multipla_escolha', 'Se o vetor já estiver 100% ordenado, quantas comparações o Selection Sort realiza?', 'Pense se o algoritmo possui mecanismo nativo de interrupção precoce sem otimização extra.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(339, 32, 'completar_lacunas', 'O laço interno do Selection Sort começa a varredura a partir da posição `_______` para ignorar os elementos já ordenados.', 'Expressão para o índice seguinte ao atual.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(340, 32, 'ordenar_blocos', 'Ordene a rotina que inicializa a busca do menor valor a cada nova passagem do laço externo:', 'Organize: Para i de 1 ate 4 Faca -> min_pos <- i -> Escreva("Buscando menor a partir de: ", i) -> FimPara.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(341, 32, 'ordenar_blocos', 'Ordene os blocos que ajustam o Selection Sort para ordenar em ordem DECRESCENTE:', 'Siga: Para j de i+1 ate 5 Faca -> Se (v[j] > v[max_pos]) Entao -> max_pos <- j -> FimSe -> FimPara.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(342, 32, 'multipla_escolha', 'O que ocorre se a condição `Se (min_pos <> i)` for omitida antes da troca no Selection Sort?', 'O programa ainda funcionará trocando o elemento com ele mesmo quando já estiver na posição correta.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(343, 33, 'multipla_escolha', 'Qual é o pré-requisito OBRIGATÓRIO para a aplicação da Busca Binária em um vetor?', 'Sem esta condição satisfeita, o algoritmo de divisão por meio falhará.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(344, 33, 'completar_lacunas', 'A Busca Binária utiliza a estratégia de solução de problemas conhecida como Divisão e _______.', 'Termo clássico da computação: Divisão e ...', 1, '2026-09-24 20:48:59', NULL, NULL),
	(345, 33, 'ordenar_blocos', 'Ordene o cálculo do ponto médio entre as posições `inicio` e `fim` em uma Busca Binária:', 'Monte: meio <- (inicio + fim) / 2.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(346, 33, 'multipla_escolha', 'Se o valor buscado for MENOR que o valor na posição do meio, como a Busca Binária ajusta seus limites?', 'Reduz o limite superior (fim) para descartar a metade direita.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(347, 33, 'completar_lacunas', 'Quantas comparações, no pior caso, a Busca Binária realiza para encontrar um elemento em um vetor ordenado de 1024 posições?', 'Considere a relação logarítmica log2(1024).', 1, '2026-09-24 20:48:59', NULL, NULL),
	(348, 33, 'ordenar_blocos', 'Ordene os blocos de inicialização das variáveis de controle da Busca Binária:', 'Monte: inicio <- 1 -> fim <- N -> achou <- falso.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(349, 33, 'ordenar_blocos', 'Ordene a estrutura do laço Enquanto que executa a Busca Binária até encontrar ou esgotar a busca:', 'Organize: Enquanto (inicio <= fim E achou = falso) Faca -> meio <- (inicio + fim) / 2 -> Testar -> FimEnquanto.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(350, 33, 'multipla_escolha', 'O que indica que o elemento buscado NÃO existe no vetor ao término do laço da Busca Binária?', 'Observe quando os ponteiros de controle se cruzam.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(351, 33, 'completar_lacunas', 'A complexidade de tempo da Busca Binária no pior caso é de classe _______.', 'Termo para a complexidade logarítmica O(log N).', 1, '2026-09-24 20:48:59', NULL, NULL),
	(352, 33, 'ordenar_blocos', 'Ordene as decisões condicionais dentro do laço da Busca Binária ao comparar o elemento do meio com o buscado:', 'Monte: Se (v[meio] = chave) achou <- verdadeiro Senao Se (chave < v[meio]) fim <- meio - 1 Senao inicio <- meio + 1.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(353, 33, 'ordenar_blocos', 'Ordene a rotina completa que verifica o resultado e informa o usuário se o valor foi encontrado ou não:', 'Siga: Se (achou = verdadeiro) Entao Escreva("Encontrado no indice: ", meio) Senao Escreva("Nao encontrado") FimSe.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(354, 33, 'multipla_escolha', 'Para um vetor DESORDENADO pequeno (ex: 5 elementos), qual abordagem é mais eficiente e simples?', 'Pense no custo extra de ter que ordenar primeiro para só depois buscar binariamente.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(355, 34, 'multipla_escolha', 'O que diferencia um Registro (Struct) de um Vetor (Array)?', 'Compare coleções homogêneas vs. coleções heterogêneas de dados.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(356, 34, 'completar_lacunas', 'Os campos individuais de um registro são acessados através do operador de _______ (símbolo ponto `.`).', 'Símbolo usado para acessar campos (ex: aluno.nome).', 1, '2026-09-24 20:48:59', NULL, NULL),
	(357, 34, 'ordenar_blocos', 'Ordene a definição de um tipo Registro para representar um Produto (nome, preco, quantidade):', 'Monte: Tipo Produto = Registro -> nome: Texto -> preco: Real -> qtd: Inteiro -> FimRegistro.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(358, 34, 'multipla_escolha', 'Como é chamada cada variável individual pertencente a uma estrutura de registro?', 'Nome técnico para as variáveis contidas dentro do Registro.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(359, 34, 'completar_lacunas', 'Na instrução `cliente.idade <- 25`, a palavra `idade` representa um _______ do registro `cliente`.', 'Termo técnico para a variável membro.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(360, 34, 'ordenar_blocos', 'Ordene o código para atribuir nome e nota a uma variável do tipo Registro `aluno1`:', 'Monte: aluno1.nome <- "Maria" -> aluno1.nota <- 9.5 -> Escreva(aluno1.nome, aluno1.nota).', 1, '2026-09-24 20:48:59', NULL, NULL),
	(361, 34, 'ordenar_blocos', 'Ordene a leitura via teclado dos dados de um funcionário (nome e salario):', 'Siga: Escreva("Nome:") -> Leia(func.nome) -> Escreva("Salario:") -> Leia(func.salario).', 1, '2026-09-24 20:48:59', NULL, NULL),
	(362, 34, 'multipla_escolha', 'Qual das alternativas representa uma declaração válida para acessar o campo `email` do registro `usuario`?', 'Atente para a sintaxe com ponto.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(363, 34, 'completar_lacunas', 'Um registro é considerado uma estrutura de dados _______ pois permite combinar tipos de dados variados no mesmo elemento.', 'O oposto de homogênea.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(364, 34, 'ordenar_blocos', 'Ordene o cálculo do valor total em estoque para um registro `prod` (preco * quantidade):', 'Organize: total <- prod.preco * prod.qtd -> Escreva("Total Estoque: R$", total).', 1, '2026-09-24 20:48:59', NULL, NULL),
	(365, 34, 'ordenar_blocos', 'Ordene a estrutura que compara se a nota de um aluno1 registrado é maior ou igual a 6.0:', 'Monte: Se (aluno1.nota >= 6.0) Entao -> Escreva(aluno1.nome, " Aprovado") -> Senao Escreva("Reprovado") -> FimSe.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(366, 34, 'multipla_escolha', 'É possível passar um Registro inteiro como parâmetro para uma Função ou Procedimento?', 'Considere se a estrutura pode ser tratada como um único bloco de dados.', 1, '2026-09-24 20:48:59', NULL, NULL),
	(367, 35, 'multipla_escolha', 'O que representa a estrutura `turma[i].nota` em um programa?', 'Identifique o vetor, a posição e o campo acessado.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(368, 35, 'completar_lacunas', 'Ao declarar um vetor de registros `produtos[1..100]`, podemos armazenar até _______ registros individuais na memória.', 'Capacidade máxima do array.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(369, 35, 'ordenar_blocos', 'Ordene o código para cadastrar 3 alunos em um vetor de registros usando o laço Para:', 'Monte: Para i de 1 ate 3 -> Leia(turma[i].nome) -> Leia(turma[i].nota) -> FimPara.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(370, 35, 'multipla_escolha', 'Qual é a forma correta de exibir o nome do terceiro produto de um vetor de registros chamado `estoque`?', 'Considere o índice do vetor e o campo do registro.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(371, 35, 'completar_lacunas', 'Para percorrer e listar todos os elementos de um vetor de registros, utilizamos um laço de repetição com a variável de controle servindo de _______ do vetor.', 'Termo para o número da posição no array.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(372, 35, 'ordenar_blocos', 'Ordene o algoritmo para calcular a média de notas de uma turma armazenada em um vetor de registros:', 'Siga: soma <- 0 -> Para i de 1 ate 3 -> soma <- soma + turma[i].nota -> FimPara -> media <- soma / 3.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(373, 35, 'ordenar_blocos', 'Ordene o código para buscar um produto pelo nome em um vetor de registros:', 'Monte: Para i de 1 ate 5 -> Se (estoque[i].nome = busca) Entao Escreva("Preco: ", estoque[i].preco) FimSe -> FimPara.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(374, 35, 'multipla_escolha', 'Ao aplicar o Bubble Sort para ordenar um vetor de registros pelo campo `preco`, o que deve ser trocado de lugar?', 'Analise se trocamos apenas a nota ou o registro inteiro com todos os seus campos.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(375, 35, 'completar_lacunas', 'A troca completa de dois registros em um vetor de structs requer uma variável auxiliar declarada com o tipo _______.', 'O tipo de dado deve coincidir com o do Registro.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(376, 35, 'ordenar_blocos', 'Ordene os blocos para listar apenas os alunos APROVADOS (nota >= 6.0) de um vetor de registros:', 'Monte: Para i de 1 ate 4 -> Se (turma[i].nota >= 6.0) Entao Escreva(turma[i].nome) FimSe -> FimPara.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(377, 35, 'ordenar_blocos', 'Ordene a troca completa de dois registros `turma[j]` e `turma[j+1]` no Bubble Sort:', 'Organize: aux_aluno <- turma[j] -> turma[j] <- turma[j+1] -> turma[j+1] <- aux_aluno.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(378, 35, 'multipla_escolha', 'Qual é o resultado de executar `Escreva(estoque[2])` sem especificar um campo em linguagens que não suportam impressão direta de structs?', 'Identifique o erro de sintaxe/tipagem ao tentar imprimir o bloco bruto.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(379, 36, 'multipla_escolha', 'O que define uma Função Recursiva na programação?', 'Considere o ato de uma função invocar o seu próprio identificador.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(380, 36, 'completar_lacunas', 'A condição de parada que impede uma função recursiva de entrar em repetição infinita é chamada de Caso _______.', 'Termo para a condição de término (ponto de parada).', 1, '2026-09-24 20:49:00', NULL, NULL),
	(381, 36, 'ordenar_blocos', 'Ordene o código da clássica função recursiva de Fatorial:', 'Monte: Funcao Fatorial(n) -> Se (n <= 1) Retorne 1 Senao Retorne n * Fatorial(n - 1) -> FimFuncao.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(382, 36, 'multipla_escolha', 'O que acontece se uma função recursiva não possuir um Caso Base bem definido?', 'Pense na memória de chamadas (stack overflow).', 1, '2026-09-24 20:49:00', NULL, NULL),
	(383, 36, 'completar_lacunas', 'Cada chamada recursiva é empilhada na memória em uma estrutura chamada Pilha de _______.', 'Nome da pilha de execução de funções (Call Stack).', 1, '2026-09-24 20:49:00', NULL, NULL),
	(384, 36, 'ordenar_blocos', 'Ordene os blocos para calcular a soma recursiva de 1 até N:', 'Siga: Funcao SomaAte(n) -> Se (n = 1) Retorne 1 Senao Retorne n + SomaAte(n - 1) -> FimFuncao.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(385, 36, 'ordenar_blocos', 'Ordene a chamada e exibição do resultado da função Fatorial para o número 4:', 'Monte: num <- 4 -> res <- Fatorial(num) -> Escreva("Fatorial de 4 e: ", res).', 1, '2026-09-24 20:49:00', NULL, NULL),
	(386, 36, 'multipla_escolha', 'Qual é o valor retornado pela chamada `Fatorial(3)` sabendo que `Fatorial(n) = n * Fatorial(n-1)` e `Fatorial(1) = 1`?', 'Calcule 3 * 2 * 1.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(387, 36, 'completar_lacunas', 'A parte da função recursiva em que a função chama a si mesma ajustando os parâmetros é o Caso _______.', 'Oposto do Caso Base.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(388, 36, 'ordenar_blocos', 'Ordene os blocos para criar uma contagem regressiva recursiva de N até 0:', 'Organize: Procedimento Regressiva(n) -> Escreva(n) -> Se (n > 0) Regressiva(n - 1) -> FimProcedimento.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(389, 36, 'ordenar_blocos', 'Ordene o cálculo recursivo da potência (base^expoente):', 'Monte: Funcao Potencia(b, e) -> Se (e = 0) Retorne 1 Senao Retorne b * Potencia(b, e - 1) -> FimFuncao.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(390, 36, 'multipla_escolha', 'Qual é a principal desvantagem da recursividade em comparação com laços iterativos simples (como Para ou Enquanto)?', 'Considere o consumo de memória da pilha de execução.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(391, 37, 'multipla_escolha', 'O que significa o conceito de Persistência de Dados em programação?', 'Pense na diferença entre memória RAM (temporária) e disco rígido (permanente).', 1, '2026-09-24 20:49:00', NULL, NULL),
	(392, 37, 'completar_lacunas', 'Para poder gravar ou ler informações em um arquivo, o programa deve realizar primeiro a instrução de _______ do arquivo.', 'Primeira ação antes do acesso aos dados.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(393, 37, 'ordenar_blocos', 'Ordene a sequência correta de operações para gravar um texto em um arquivo:', 'Monte: Abrir Arquivo (Escrita) -> Escrever Linha -> Fechar Arquivo.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(394, 37, 'multipla_escolha', 'O que ocorre com as variáveis armazenadas apenas na memória RAM quando o programa é encerrado?', 'A memória volátil é totalmente limpa pelo sistema operacional.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(395, 37, 'completar_lacunas', 'Após concluir todas as operações de leitura ou escrita, devemos obrigatoriamente executar o comando para _______ o arquivo.', 'Liberação do ponteiro de arquivo no sistema.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(396, 37, 'ordenar_blocos', 'Ordene os blocos para abrir um arquivo em modo leitura e exibir seu conteúdo:', 'Monte: Abrir "dados.txt" para Leitura -> LerLinha(arq, texto) -> Escreva(texto) -> Fechar(arq).', 1, '2026-09-24 20:49:00', NULL, NULL),
	(397, 37, 'ordenar_blocos', 'Ordene a gravação de um vetor de 3 nomes em um arquivo de texto:', 'Siga: Abrir "nomes.txt" -> Para i de 1 ate 3 -> EscreverLinha(arq, nomes[i]) -> FimPara -> Fechar(arq).', 1, '2026-09-24 20:49:00', NULL, NULL),
	(398, 37, 'multipla_escolha', 'Qual é a diferença entre abrir um arquivo no modo "Escrita (Overwrite)" e no modo "Anexo (Append)"?', 'Considere se o conteúdo pré-existente no arquivo é apagado ou mantido.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(399, 37, 'completar_lacunas', 'A sigla EOF (End Of File) indica que o leitor atingiu o _______ do arquivo.', 'Termo para o término do arquivo.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(400, 37, 'ordenar_blocos', 'Ordene o laço que lê todas as linhas de um arquivo até atingir o fim do arquivo (EOF):', 'Organize: Enquanto (NAO FimDoArquivo(arq)) Faca -> LerLinha(arq, linha) -> Escreva(linha) -> FimEnquanto.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(401, 37, 'ordenar_blocos', 'Ordene o salvamento de um Registro `aluno` (nome e nota) formatado com separador:', 'Monte: linha <- aluno.nome + ";" + aluno.nota -> Abrir "aluno.txt" -> EscreverLinha(arq, linha) -> Fechar(arq).', 1, '2026-09-24 20:49:00', NULL, NULL),
	(402, 37, 'multipla_escolha', 'O que acontece ao tentar ler um arquivo que NÃO existe no disco sem o devido tratamento de erro?', 'Considere a falha do sistema por arquivo não encontrado.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(403, 38, 'multipla_escolha', 'O que é o conceito de Defensive Programming (Programação Defensiva)?', 'Antecipar possíveis falhas e dados incorretos para evitar a parada do sistema.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(404, 38, 'completar_lacunas', 'O erro clássico de tentar dividir um valor por zero gera uma falha de execução conhecida como exceção de _______.', 'Operação matemática proibida.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(405, 38, 'ordenar_blocos', 'Ordene o código de validação que impede a divisão por zero antes de efetuar o cálculo:', 'Monte: Se (denominador = 0) Escreva("Erro: Divisao por zero") Senao res <- num / den FimSe.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(406, 38, 'multipla_escolha', 'Qual é a estratégia ideal quando o usuário digita um valor inválido (ex: idade negativa)?', 'Repetir a solicitação até que o valor fornecido cumpra as regras.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(407, 38, 'completar_lacunas', 'A técnica de verificar se os dados informados pelo usuário atendem aos requisitos antes de processá-los é chamada de _______ de dados.', 'Processo de checagem da validade.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(408, 38, 'ordenar_blocos', 'Ordene o laço de validação para garantir a leitura de uma idade positiva (>= 0):', 'Siga: Faca -> Escreva("Digite a idade:") -> Leia(idade) -> Enquanto (idade < 0).', 1, '2026-09-24 20:49:00', NULL, NULL),
	(409, 38, 'ordenar_blocos', 'Ordene a validação de limite de índice para evitar acesso inválido a um vetor de 10 posições:', 'Monte: Se (idx >= 1 E idx <= 10) Entao Escreva(v[idx]) Senao Escreva("Indice invalido") FimSe.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(410, 38, 'multipla_escolha', 'O que caracteriza um erro de tempo de execução (Runtime Error) em oposição a um erro de compilação?', 'O código compila com sintaxe correta, mas falha durante a execução.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(411, 38, 'completar_lacunas', 'A estrutura condicional `Tente ... Capture` (Try-Catch) é utilizada para tratar _______ durante a execução.', 'Termo para erros que ocorrem em tempo de execução.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(412, 38, 'ordenar_blocos', 'Ordene a validação de uma nota escolar que deve estar contida no intervalo [0.0, 10.0]:', 'Organize: Faca -> Leia(nota) -> Se (nota < 0 OU nota > 10) Escreva("Invalida!") -> Enquanto (nota < 0 OU nota > 10).', 1, '2026-09-24 20:49:00', NULL, NULL),
	(413, 38, 'ordenar_blocos', 'Ordene o bloco de verificação de string não vazia antes de cadastrar um nome:', 'Monte: Se (nome = "") Entao Escreva("Nome nao pode ser vazio") Senao Cadastrar(nome) FimSe.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(414, 38, 'multipla_escolha', 'Qual é a principal consequência de NÃO validar as entradas de dados em um sistema comercial?', 'Pense na corrupção de banco de dados, falhas de segurança e travamento do programa.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(415, 39, 'multipla_escolha', 'O que define o conceito de "Clean Code" (Código Limpo)?', 'Código escrito para ser facilmente lido, compreendido e mantido por outros programadores.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(416, 39, 'completar_lacunas', 'A técnica de depuração que consiste em acompanhar a alteração das variáveis passo a passo no papel é o Teste de _______.', 'Acompanhamento manual da execução.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(417, 39, 'ordenar_blocos', 'Ordene o exemplo que aplica nomes expressivos de variáveis em vez de letras genéricas:', 'Monte: salario_bruto <- 2500.0 -> percentual_desconto <- 0.1 -> salario_liquido <- salario_bruto * (1 - percentual_desconto).', 1, '2026-09-24 20:49:00', NULL, NULL),
	(418, 39, 'multipla_escolha', 'O que é um Breakpoint (Ponto de Parada) no contexto de uma ferramenta de depuração (Debugger)?', 'Ponto no código onde a execução é pausada para inspeção do estado.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(419, 39, 'completar_lacunas', 'O alinhamento visual do código-fonte para demonstrar a hierarquia dos blocos e comandos é chamado de _______.', 'Espaçamento estrutural do código.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(420, 39, 'ordenar_blocos', 'Ordene o código devidamente indentado para a leitura e teste de uma condição:', 'Siga: Se (ativo = verdadeiro) Entao ->    Escreva("Acesso Liberado") -> Senao ->    Escreva("Bloqueado") -> FimSe.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(421, 39, 'ordenar_blocos', 'Ordene os passos para realizar a depuração de um erro lógico em um programa:', 'Monte: Inserir Breakpoint -> Iniciar Depuração -> Inspecionar Variáveis -> Identificar Falha -> Corrigir.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(422, 39, 'multipla_escolha', 'Qual das opções apresenta o pior nome de variável para armazenar o valor da média final de um estudante?', 'Nomes de uma única letra genérica sem contexto.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(423, 39, 'completar_lacunas', 'Comentários no código devem explicar o _______ da solução e não o que o próprio comando óbvio já demonstra.', 'O motivo/propósito da decisão de código.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(424, 39, 'ordenar_blocos', 'Ordene a restruturação de um bloco de código confuso em uma função modular expressiva:', 'Organize: Funcao EhMaiorDeIdade(idade) -> Retorne (idade >= 18) -> FimFuncao.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(425, 39, 'ordenar_blocos', 'Ordene o refatoramento de uma expressão mágica (número solto) usando uma constante nomeada:', 'Monte: LIMITE_MAXIMO <- 100 -> Se (quantidade > LIMITE_MAXIMO) Entao Escreva("Limite excedido") FimSe.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(426, 39, 'multipla_escolha', 'Por que é importante evitar "Números Mágicos" (valores numéricos fixos soltos no meio do código)?', 'Substituir valores por constantes facilita mudanças futuras no projeto.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(427, 40, 'multipla_escolha', 'Qual é a ordem lógica recomendada para processar dados em um sistema corporativo completo (CRUD)?', 'Carregar -> Interagir/Processar -> Salvar.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(428, 40, 'completar_lacunas', 'A sigla CRUD representa as quatro operações fundamentais em sistemas de informação: Create, Read, Update e _______.', 'Termo em inglês para a exclusão/remoção de registros.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(429, 40, 'ordenar_blocos', 'Ordene o fluxo de inicialização do Projeto Final:', 'Monte: CarregarDadosDoArquivo() -> ExibirMenu() -> ProcessarOpcao() -> SalvarDadosNoArquivo().', 1, '2026-09-24 20:49:00', NULL, NULL),
	(430, 40, 'multipla_escolha', 'Qual das combinações de conhecimentos do Módulo 4 permite buscar um produto em milissegundos em uma base com 100.000 itens?', 'Pense na relação entre Ordenação + Busca Binária.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(431, 40, 'completar_lacunas', 'Ao dominar a lógica de programação estruturada em pseudocódigo, a transição para linguagens como C++, Java ou Python requer apenas o aprendizado da nova _______.', 'Regra de escrita/código da linguagem.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(432, 40, 'ordenar_blocos', 'Ordene os blocos da função de busca e exibição de um aluno no Projeto Integrador:', 'Monte: Ler busca -> pos <- BuscaBinaria(turma, busca) -> Se (pos <> -1) Exibir(turma[pos]) Senao AVISO -> FimSe.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(433, 40, 'ordenar_blocos', 'Ordene a rotina que salva todo o vetor de registros no arquivo ao encerrar o sistema:', 'Siga: Abrir "dados.dat" -> Para i de 1 ate total -> EscreverRegistro(arq, lista[i]) -> FimPara -> Fechar(arq).', 1, '2026-09-24 20:49:00', NULL, NULL),
	(434, 40, 'multipla_escolha', 'O que deve ser feito ANTES de executar uma Busca Binária em um vetor de registros recém-carregado do arquivo?', 'A busca binária exige a garantia de ordenação prévia.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(435, 40, 'completar_lacunas', 'O isolamento da lógica do sistema em funções independentes evita o efeito colateral de bugs se espalharem por todo o _______.', 'O arquivo/bloco de código.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(436, 40, 'ordenar_blocos', 'Ordene a lógica da opção "Remover Registro" em um vetor shiftando os elementos à esquerda:', 'Monte: Para i de pos ate total-1 -> lista[i] <- lista[i+1] -> FimPara -> total <- total - 1.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(437, 40, 'ordenar_blocos', 'Ordene o fechamento seguro do Projeto Final:', 'Organize: SalvarDadosArquivo() -> Escreva("Dados salvos com sucesso!") -> Escreva("Programa Encerrado.").', 1, '2026-09-24 20:49:00', NULL, NULL),
	(438, 40, 'multipla_escolha', 'Ao finalizar os 4 Módulos de Lógica de Programação, qual é a postura recomendada para evoluir como desenvolvedor?', 'Praticar projetos reais, aprender uma linguagem de mercado e estudar Orientação a Objetos / Estrutura de Dados avançadas.', 1, '2026-09-24 20:49:00', NULL, NULL),
	(439, 41, 'multipla_escolha', 'Qual diretiva é utilizada no início de um programa em C++ para incluir a biblioteca padrão de fluxo de entrada e saída?', 'Lembre-se da biblioteca responsável pelos comandos cin e cout.', 1, '2026-09-28 10:35:52', NULL, NULL),
	(440, 41, 'completar_lacunas', 'Para utilizar comandos como cout e cin sem a necessidade de antecedê-los com o prefixo std::, declaramos a instrução using namespace _______;', 'Informe o espaço de nomes padrão do C++.', 1, '2026-09-28 10:35:52', NULL, NULL),
	(441, 41, 'ordenar_blocos', 'Ordene os blocos para formar a estrutura básica e funcional de um programa em C++:', 'Organize: Inclusão da biblioteca -> Namespace -> Função main -> Retorno -> Fechamento.', 1, '2026-09-28 10:35:52', NULL, NULL),
	(442, 41, 'multipla_escolha', 'Qual é o nome da função obrigatória que serve como ponto de entrada para a execução de qualquer programa em C++?', 'É a função principal de execução.', 1, '2026-09-28 10:35:52', NULL, NULL),
	(443, 41, 'completar_lacunas', 'A instrução _______ 0; no final da função main indica ao sistema operacional que o programa executou e encerrou com sucesso.', 'Palavra-chave para retornar um valor ao término da função.', 1, '2026-09-28 10:35:52', NULL, NULL),
	(444, 41, 'ordenar_blocos', 'Ordene os blocos para exibir a mensagem "Ola Mundo" no terminal seguida de uma quebra de linha:', 'Organize: Comando cout -> Operador << -> Mensagem -> Operador << -> endl e ponto e vírgula.', 1, '2026-09-28 10:35:52', NULL, NULL),
	(445, 41, 'ordenar_blocos', 'Ordene os blocos das diretivas iniciais de um código C++:', 'Siga: Inclusão do iostream -> Declaração do namespace std.', 1, '2026-09-28 10:35:52', NULL, NULL),
	(446, 41, 'multipla_escolha', 'Qual caractere é obrigatoriamente utilizado ao final da maioria das instruções em C++ para sinalizar o fim de um comando?', 'Mesmo caractere de finalização usado na maioria das linguagens C-like.', 1, '2026-09-28 10:35:52', NULL, NULL),
	(447, 41, 'completar_lacunas', 'Para inserir um comentário de apenas uma linha em C++, utilizamos os dois caracteres _______ no início do texto.', 'Símbolo de comentário de linha única.', 1, '2026-09-28 10:35:52', NULL, NULL),
	(448, 41, 'ordenar_blocos', 'Ordene os blocos para escrever um programa C++ completo que imprime a palavra "Inicio" sem usar a cláusula using namespace std:', 'Monte: Inclusão -> int main() -> std::cout << "Inicio"; -> return 0; -> }.', 1, '2026-09-28 10:35:52', NULL, NULL),
	(449, 42, 'multipla_escolha', 'Qual tipo de dado é utilizado em C++ para declarar uma variável que armazenará um número inteiro?', 'Tipo de dado numérico sem casas decimais.', 1, '2026-09-28 10:37:00', NULL, NULL),
	(450, 42, 'completar_lacunas', 'Para declarar uma variável que armazena textos e cadeias de caracteres em C++, utilizamos o tipo de dado _______.', 'Tipo utilizado para frases e palavras completas.', 1, '2026-09-28 10:37:00', NULL, NULL),
	(451, 42, 'ordenar_blocos', 'Ordene os blocos para declarar e inicializar corretamente uma variável inteira chamada idade com o valor 20 em C++:', 'Siga: Tipo -> Nome -> Atribuição -> Valor -> Ponto e vírgula.', 1, '2026-09-28 10:37:00', NULL, NULL),
	(452, 42, 'multipla_escolha', 'Qual operador de inserção em fluxo é utilizado junto ao cout para enviar textos e variáveis para o terminal?', 'É o operador direcionador apontando para a esquerda.', 1, '2026-09-28 10:37:00', NULL, NULL),
	(453, 42, 'completar_lacunas', 'O tipo de dado primitivo _______ é utilizado em C++ para armazenar valores lógicos (true ou false).', 'Apenas 4 letras em inglês para booleano.', 1, '2026-09-28 10:37:00', NULL, NULL),
	(454, 42, 'ordenar_blocos', 'Ordene os blocos para concatenar o texto "Idade: " com o valor da variável idade e finalizar com quebra de linha:', 'Monte: cout -> Texto -> Variável -> endl e ponto e vírgula.', 1, '2026-09-28 10:37:00', NULL, NULL),
	(455, 42, 'ordenar_blocos', 'Ordene os blocos para declarar uma variável do tipo caractere simples chamada letra contendo a letra \'A\':', 'Atenção para o uso de aspas simples para tipo char.', 1, '2026-09-28 10:37:00', NULL, NULL),
	(456, 42, 'multipla_escolha', 'Qual manipulador do C++ é enviado ao cout para realizar uma quebra de linha e limpar o buffer de saída?', 'Termina com a letra l e significa "end line".', 1, '2026-09-28 10:37:00', NULL, NULL),
	(457, 42, 'completar_lacunas', 'Para declarar números decimais com maior precisão de casas decimais em C++, utilizamos o tipo de dado _______.', 'Tipo de precisão dupla em ponto flutuante.', 1, '2026-09-28 10:37:00', NULL, NULL),
	(458, 42, 'ordenar_blocos', 'Ordene os blocos para criar um programa C++ simples que declara um preço decimal e o exibe no terminal:', 'Organize: Tipo float com valor -> Comando cout -> Retorno zero.', 1, '2026-09-28 10:37:00', NULL, NULL),
	(459, 43, 'multipla_escolha', 'Qual comando em C++ é equivalente ao comando "leia" do Portugol para capturar dados digitados no teclado?', 'Pense no comando de entrada (input) em C++.', 1, '2026-09-28 10:39:33', NULL, NULL),
	(460, 43, 'completar_lacunas', 'Enquanto o comando cout utiliza o operador de inserção <<, o comando cin utiliza o operador de extração _______ para direcionar o valor lido para a variável.', 'Informe os dois caracteres do operador de extração apontando para a direita.', 1, '2026-09-28 10:39:33', NULL, NULL),
	(461, 43, 'ordenar_blocos', 'Ordene os blocos para realizar a leitura do valor digitado pelo usuário para a variável inteira idade:', 'Siga: Comando cin -> Operador >> -> Variável -> Ponto e vírgula.', 1, '2026-09-28 10:39:33', NULL, NULL),
	(462, 43, 'multipla_escolha', 'Qual é a orientação correta dos operadores ao utilizar o comando cin em C++?', 'As setas do cin apontam para a direita (em direção à variável).', 1, '2026-09-28 10:39:33', NULL, NULL),
	(463, 43, 'completar_lacunas', 'O comando cin pertence ao namespace _______, podendo ser escrito como std::cin caso o namespace não tenha sido declarado.', 'Informe o nome do namespace padrão.', 1, '2026-09-28 10:39:33', NULL, NULL),
	(464, 43, 'ordenar_blocos', 'Ordene os blocos para exibir uma mensagem solicitando um número e, em seguida, fazer a leitura desse número (equivalente ao leia(numero) do Portugol):', 'Exiba primeiro a mensagem com cout e depois leia com cin.', 1, '2026-09-28 10:39:33', NULL, NULL),
	(465, 43, 'ordenar_blocos', 'Ordene os blocos para ler dois valores em sequência usando uma única instrução cin:', 'Encadeie as duas variáveis utilizando o operador >>.', 1, '2026-09-28 10:39:33', NULL, NULL),
	(466, 43, 'multipla_escolha', 'O que acontece ao tentar compilar um código em C++ utilizando o operador de saída << junto com o comando cin (ex: cin << numero;)?', 'O compilador identifica o operador incorreto para a operação de entrada.', 1, '2026-09-28 10:39:33', NULL, NULL),
	(467, 43, 'completar_lacunas', 'Para capturar um valor numérico ou texto simples sem espaços digitado pelo usuário, usamos a instrução _______ >> variavel;', 'Informe o comando de entrada de dados do C++.', 1, '2026-09-28 10:39:33', NULL, NULL),
	(468, 43, 'ordenar_blocos', 'Ordene os blocos para criar a estrutura de leitura de uma nota decimal do aluno (tipo float):', 'Declare a variável float -> Escreva a mensagem no terminal -> Leia o valor com cin.', 1, '2026-09-28 10:39:33', NULL, NULL),
	(469, 44, 'multipla_escolha', 'Qual operador é utilizado em C++ para calcular o resto da divisão inteira, assim como no Portugol?', 'Lembre-se do símbolo de porcentagem.', 1, '2026-09-28 10:41:25', NULL, NULL),
	(470, 44, 'completar_lacunas', 'Para realizar a operação de divisão em C++, utilizamos o símbolo da barra _______.', 'Informe apenas o caractere da barra de divisão.', 1, '2026-09-28 10:41:25', NULL, NULL),
	(471, 44, 'ordenar_blocos', 'Ordene os blocos para calcular a média de duas variáveis inteiras (nota1 e nota2) e atribuir à variável media:', 'Atenção ao uso dos parênteses para garantir a prioridade da soma antes da divisão.', 1, '2026-09-28 10:41:25', NULL, NULL),
	(472, 44, 'multipla_escolha', 'Qual é o resultado da expressão inteira 7 / 2 em C++, considerando que ambos os números são do tipo int?', 'A divisão entre dois inteiros em C++ descarta as casas decimais.', 1, '2026-09-28 10:41:25', NULL, NULL),
	(473, 44, 'completar_lacunas', 'Para somar dois valores em C++, utilizamos o operador aritmético _______ entre as variáveis.', 'Símbolo básico de adição.', 1, '2026-09-28 10:41:25', NULL, NULL),
	(474, 44, 'ordenar_blocos', 'Ordene os blocos para ler dois números, calcular a soma entre eles e exibir o resultado no terminal:', 'Siga: Leitura -> Cálculo da soma -> Exibição.', 1, '2026-09-28 10:41:25', NULL, NULL),
	(475, 44, 'ordenar_blocos', 'Ordene os blocos para declarar as variáveis, ler um número inteiro e calcular o seu quádruplo (multiplicado por 4):', 'Monte: Declaração -> Leitura -> Cálculo -> Exibição.', 1, '2026-09-28 10:41:25', NULL, NULL),
	(476, 44, 'multipla_escolha', 'Qual dos seguintes símbolos é utilizado em C++ para realizar a operação de multiplicação?', 'O mesmo caractere de asterisco utilizado no Portugol.', 1, '2026-09-28 10:41:25', NULL, NULL),
	(477, 44, 'completar_lacunas', 'O operador de resto da divisão (%) em C++ deve ser utilizado apenas com valores do tipo _______.', 'Tipo de dado para números inteiros sem casas decimais.', 1, '2026-09-28 10:41:25', NULL, NULL),
	(478, 44, 'ordenar_blocos', 'Ordene os blocos para ler um número inteiro, calcular o resto da sua divisão por 2 e exibir o resultado:', 'Monte: Declaração -> Leitura -> Resto da divisão (%) -> Exibição.', 1, '2026-09-28 10:41:25', NULL, NULL),
	(479, 45, 'multipla_escolha', 'Qual operador relacional em C++ verifica se dois valores são iguais, equivalente ao sinal de igual (=) do Portugol?', 'Em C++, o sinal único = é atribuição; a comparação exige dois sinais de igual.', 1, '2026-09-28 10:43:07', NULL, NULL),
	(480, 45, 'completar_lacunas', 'O operador lógico "e" do Portugol é representado em C++ pelos caracteres _______.', 'Informe os dois símbolos do comercial (e comercial duplo).', 1, '2026-09-28 10:43:07', NULL, NULL),
	(481, 45, 'ordenar_blocos', 'Ordene os blocos para formar uma expressão lógica que verifica se um número está entre 10 e 20 (inclusive):', 'Combine as duas condições usando o operador lógico "e" (&&).', 1, '2026-09-28 10:43:07', NULL, NULL),
	(482, 45, 'multipla_escolha', 'Qual operador em C++ é utilizado para verificar a diferença entre dois valores (diferente de), correspondendo ao <> do Portugol?', 'O operador é formado pelo ponto de exclamação seguido do sinal de igual.', 1, '2026-09-28 10:43:07', NULL, NULL),
	(483, 45, 'completar_lacunas', 'O operador lógico de negação "nao" do Portugol é representado em C++ pelo símbolo _______.', 'Símbolo do ponto de exclamação.', 1, '2026-09-28 10:43:07', NULL, NULL),
	(484, 45, 'ordenar_blocos', 'Ordene os blocos para atribuir à variável booleana "aprovado" o resultado do teste se a nota é maior ou igual a 7:', 'Monte: Variável booleana -> Condição entre parênteses -> Ponto e vírgula.', 1, '2026-09-28 10:43:07', NULL, NULL),
	(485, 45, 'ordenar_blocos', 'Ordene os blocos para verificar se a variável "idade" é menor que 18 OU maior que 60:', 'Utilize o operador lógico || entre as duas comparações.', 1, '2026-09-28 10:43:07', NULL, NULL),
	(486, 45, 'multipla_escolha', 'Qual é a representação em C++ para o operador lógico "ou" do Portugol?', 'Representado por duas barras verticais (pipe duplo).', 1, '2026-09-28 10:43:07', NULL, NULL),
	(487, 45, 'completar_lacunas', 'Para testar se o valor de uma variável x é maior ou igual a 100 em C++, escrevemos x _______ 100.', 'Informe os dois caracteres do operador maior ou igual.', 1, '2026-09-28 10:43:07', NULL, NULL),
	(488, 45, 'ordenar_blocos', 'Ordene os blocos para declarar uma variável booleana e armazenar o resultado da verificação se num é diferente de zero:', 'Siga: Declaração e atribuição -> Teste de diferença com ponto e vírgula.', 1, '2026-09-28 10:43:07', NULL, NULL),
	(489, 46, 'multipla_escolha', 'Qual palavra-chave em C++ corresponde ao comando "se" do Portugol para iniciar uma estrutura condicional?', 'A instrução condicional básica em inglês é "if".', 1, '2026-09-28 10:44:07', NULL, NULL),
	(490, 46, 'completar_lacunas', 'Para executar um bloco de código alternativo caso a condição do if seja falsa, utilizamos a palavra-chave _______.', 'Sua tradução equivale ao comando "senao" do Portugol.', 1, '2026-09-28 10:44:07', NULL, NULL),
	(491, 46, 'ordenar_blocos', 'Ordene os blocos para criar uma estrutura condicional simples que verifica se uma nota é maior ou igual a 7 e exibe a mensagem "Aprovado":', 'Monte: Condição do if -> Comando de exibição -> Fechamento de chaves.', 1, '2026-09-28 10:44:07', NULL, NULL),
	(492, 46, 'multipla_escolha', 'Qual das opções representa a sintaxe correta de uma estrutura condicional composta em C++?', 'A condição deve estar entre parênteses e os blocos delimitados por chaves.', 1, '2026-09-28 10:44:07', NULL, NULL),
	(493, 46, 'completar_lacunas', 'Para delimitar o bloco de código que será executado dentro da estrutura if ou else em C++, utilizamos o par de _______.', 'Símbolos gráficos { e } usados para blocos de código.', 1, '2026-09-28 10:44:07', NULL, NULL),
	(494, 46, 'ordenar_blocos', 'Ordene os blocos para verificar se a variável idade é maior ou igual a 18 e exibir "Maior de idade", ou caso contrário, exibir "Menor de idade":', 'Monte a estrutura completa com if e else.', 1, '2026-09-28 10:44:07', NULL, NULL),
	(495, 46, 'ordenar_blocos', 'Ordene os blocos para ler um número inteiro e verificar se ele é positivo (maior que zero):', 'Monte: Declaração -> Leitura -> Condição if -> Exibição -> Fechamento.', 1, '2026-09-28 10:44:07', NULL, NULL),
	(496, 46, 'multipla_escolha', 'O que acontece em um programa C++ caso a condição testada no comando if seja falsa e não exista uma instrução else definida?', 'Sem o else, o programa simplesmente ignora o bloco do if.', 1, '2026-09-28 10:44:07', NULL, NULL),
	(497, 46, 'completar_lacunas', 'A instrução condicional "se (x > 0)" em Portugol é traduzida diretamente para C++ como "_______ (x > 0)".', 'Palavra-chave em inglês para a instrução condicional.', 1, '2026-09-28 10:44:07', NULL, NULL),
	(498, 46, 'ordenar_blocos', 'Ordene os blocos para verificar se um número inteiro é par (resto da divisão por 2 igual a zero) e exibir "Par":', 'Utilize o operador % para o resto da divisão no teste do if.', 1, '2026-09-28 10:44:07', NULL, NULL),
	(499, 47, 'multipla_escolha', 'Qual instrução em C++ equivale ao "senao se" do Portugol para testar múltiplas condições em sequência?', 'Instrução em inglês formada por duas palavras separadas por espaço.', 1, '2026-09-28 10:45:22', NULL, NULL),
	(500, 47, 'completar_lacunas', 'A estrutura de seleção múltipla equivalente ao "escolha caso" do Portugol é iniciada em C++ pela instrução _______.', 'Palavra-chave em inglês para troca/seleção.', 1, '2026-09-28 10:45:22', NULL, NULL),
	(501, 47, 'ordenar_blocos', 'Ordene os blocos para criar uma estrutura encadeada com else if que exibe "Aprovado" (nota >= 7), "Recuperacao" (nota >= 5) ou "Reprovado":', 'Monte a sequência: if -> else if -> else.', 1, '2026-09-28 10:45:22', NULL, NULL),
	(502, 47, 'multipla_escolha', 'No comando switch em C++, qual instrução é utilizada no final de cada caso para interromper a execução e sair da estrutura?', 'Comando de interrupção em inglês.', 1, '2026-09-28 10:45:22', NULL, NULL),
	(503, 47, 'completar_lacunas', 'Dentro do comando switch, a opção padrão equivalente ao "caso contrario" do Portugol é declarada com a palavra-chave _______.', 'Termo em inglês para padrão/omissão.', 1, '2026-09-28 10:45:22', NULL, NULL),
	(504, 47, 'ordenar_blocos', 'Ordene os blocos para montar a estrutura básica de um switch testando o valor 1 da variável opcao:', 'Siga: Abertura do switch -> Declaração do case 1 -> Encerramento com break.', 1, '2026-09-28 10:45:22', NULL, NULL),
	(505, 47, 'ordenar_blocos', 'Ordene os blocos para estruturar os testes das condições de uma média escolar usando if e else if:', 'Organize do maior critério para o menor.', 1, '2026-09-28 10:45:22', NULL, NULL),
	(506, 47, 'multipla_escolha', 'Qual dos seguintes tipos de dados NÃO pode ser utilizado diretamente na expressão de um comando switch em C++?', 'O switch em C++ exige tipos integrais ou caracteres.', 1, '2026-09-28 10:45:22', NULL, NULL),
	(507, 47, 'completar_lacunas', 'Cada valor individual testado dentro de uma estrutura switch em C++ é precedido pela palavra-chave _______.', 'Equivalente ao "caso" do Portugol.', 1, '2026-09-28 10:45:22', NULL, NULL),
	(508, 47, 'ordenar_blocos', 'Ordene os blocos para tratar o caso padrão (caso contrário) dentro de uma estrutura switch:', 'Siga: Rótulo default -> Mensagem de erro -> Comando break.', 1, '2026-09-28 10:45:22', NULL, NULL),
	(509, 48, 'multipla_escolha', 'Qual palavra-chave em C++ substitui a estrutura de repetição "enquanto" do Portugol?', 'Palavra-chave em inglês para a repetição "enquanto".', 1, '2026-09-28 10:45:44', NULL, NULL),
	(510, 48, 'completar_lacunas', 'Para criar um laço que repete um bloco de código enquanto uma condição for verdadeira em C++, utilizamos a instrução _______ (condicao).', 'Informe o comando do laço em inglês.', 1, '2026-09-28 10:45:44', NULL, NULL),
	(511, 48, 'ordenar_blocos', 'Ordene os blocos para criar um laço while que exibe os números de 1 a 5 no terminal:', 'Declare a variável, defina a condição no while e incremente ao final do bloco.', 1, '2026-09-28 10:45:44', NULL, NULL),
	(512, 48, 'multipla_escolha', 'O que acontece durante a execução do programa caso a variável de controle dentro do laço while nunca seja alterada?', 'Se a condição for sempre verdadeira, a repetição nunca para.', 1, '2026-09-28 10:45:44', NULL, NULL),
	(513, 48, 'completar_lacunas', 'Para incrementar o valor de uma variável inteira em 1 unidade dentro do laço while, podemos utilizar o operador de incremento _______.', 'Símbolo duplo de adição.', 1, '2026-09-28 10:45:44', NULL, NULL),
	(514, 48, 'ordenar_blocos', 'Ordene os blocos para realizar uma contagem regressiva de 5 até 1 usando o laço while:', 'Inicialize em 5, decremente a variável a cada repetição e pare quando for menor que 1.', 1, '2026-09-28 10:45:44', NULL, NULL),
	(515, 48, 'ordenar_blocos', 'Ordene os blocos para ler números inteiros do usuário enquanto o número digitado for diferente de zero:', 'Leia o primeiro valor antes de testar a condição do while.', 1, '2026-09-28 10:45:44', NULL, NULL),
	(516, 48, 'multipla_escolha', 'O laço while em C++ realiza o teste da sua condição de parada em qual momento da execução?', 'Assim como no "enquanto" do Portugol, a verificação ocorre antes de entrar no bloco.', 1, '2026-09-28 10:45:44', NULL, NULL),
	(517, 48, 'completar_lacunas', 'A estrutura "enquanto (x < 10)" do Portugol é traduzida diretamente para C++ como "_______ (x < 10)".', 'Comando equivalente para o laço enquanto.', 1, '2026-09-28 10:45:44', NULL, NULL),
	(518, 48, 'ordenar_blocos', 'Ordene os blocos para solicitar a senha do usuário repetidamente até que ele digite a senha correta (1234):', 'Monte: Leitura inicial -> Teste de diferença no while -> Nova leitura dentro do bloco.', 1, '2026-09-28 10:45:44', NULL, NULL),
	(519, 49, 'multipla_escolha', 'Qual palavra-chave em C++ equivale à estrutura de repetição "para" do Portugol?', 'Tradução em inglês para o laço de repetição determinado.', 1, '2026-09-28 10:46:57', NULL, NULL),
	(520, 49, 'completar_lacunas', 'O cabeçalho do laço for em C++ é composto por três partes separadas por ponto e vírgula: inicialização, condição e _______.', 'Etapa responsável por alterar o valor da variável de controle a cada iteração.', 1, '2026-09-28 10:46:57', NULL, NULL),
	(521, 49, 'ordenar_blocos', 'Ordene os blocos para criar um laço for em C++ que conta de 1 a 10 e exibe cada número:', 'Monte o cabeçalho do for (inicialização; condição; incremento) e o bloco de exibição.', 1, '2026-09-28 10:46:57', NULL, NULL),
	(522, 49, 'multipla_escolha', 'Qual caractere é obrigatoriamente utilizado para separar as três seções do cabeçalho do laço for em C++?', 'Mesmo caractere de finalização de comandos em C++.', 1, '2026-09-28 10:46:57', NULL, NULL),
	(523, 49, 'completar_lacunas', 'A estrutura "para (i de 1 ate 5)" do Portugol é traduzida em C++ iniciando com a palavra-chave _______ (int i = 1; i <= 5; i++).', 'Comando equivalente ao "para".', 1, '2026-09-28 10:46:57', NULL, NULL),
	(524, 49, 'ordenar_blocos', 'Ordene os blocos para criar um laço for em decremento que realiza uma contagem regressiva de 10 até 1:', 'Inicialize i em 10, teste i >= 1 e decremente i a cada passo.', 1, '2026-09-28 10:46:57', NULL, NULL),
	(525, 49, 'ordenar_blocos', 'Ordene os blocos para somar os números inteiros de 1 a 5 dentro de uma variável acumuladora utilizando o laço for:', 'Declare o acumulador antes do laço e acumule a variável de controle no bloco.', 1, '2026-09-28 10:46:57', NULL, NULL),
	(526, 49, 'multipla_escolha', 'Qual é a principal vantagem de utilizar o laço for em relação ao laço while quando se sabe com antecedência o número de repetições?', 'O for concentra o controle da repetição de forma compacta.', 1, '2026-09-28 10:46:57', NULL, NULL),
	(527, 49, 'completar_lacunas', 'Para decrementar a variável de controle em 1 unidade a cada repetição de um laço for em C++, utilizamos o operador de decremento _______.', 'Símbolo duplo de subtracção.', 1, '2026-09-28 10:46:57', NULL, NULL),
	(528, 49, 'ordenar_blocos', 'Ordene os blocos para criar um laço for que exibe os números pares de 2 a 10 (incrementando de 2 em 2):', 'Use o operador de atribuição composta (i += 2) para o passo.', 1, '2026-09-28 10:46:57', NULL, NULL),
	(529, 50, 'multipla_escolha', 'Qual estrutura de repetição em C++ corresponde ao "faca... enquanto" do Portugol, garantindo que o bloco seja executado ao menos uma vez?', 'A estrutura executa primeiro o bloco e testa a condição ao final.', 1, '2026-09-28 10:47:37', NULL, NULL),
	(530, 50, 'completar_lacunas', 'Para criar um laço com teste no final em C++, iniciamos o bloco de código com a palavra-chave _______ e encerramos com while(condicao);.', 'Palavra-chave em inglês para o verbo "fazer".', 1, '2026-09-28 10:47:37', NULL, NULL),
	(531, 50, 'ordenar_blocos', 'Ordene os blocos para criar uma estrutura do-while em C++ que lê uma opção e repete enquanto o valor for diferente de zero:', 'Inicie com do, coloque a leitura dentro das chaves e termine com while(opcao != 0);.', 1, '2026-09-28 10:47:37', NULL, NULL),
	(532, 50, 'multipla_escolha', 'Na transição do Portugol para o C++, qual é o tipo de dado equivalente ao tipo "cadeia" para armazenar textos?', 'Tipo de dado da biblioteca padrão para frases e sequências de caracteres.', 1, '2026-09-28 10:47:37', NULL, NULL),
	(533, 50, 'completar_lacunas', 'Para evitar escrever std:: antes dos comandos cout e cin em todo o código, declaramos a instrução using namespace _______; no início.', 'Nome do namespace padrão do C++.', 1, '2026-09-28 10:47:37', NULL, NULL),
	(534, 50, 'ordenar_blocos', 'Ordene os blocos para formar a estrutura completa de um programa em C++ que lê um número inteiro e o exibe no terminal:', 'Siga: Diretiva -> Namespace -> int main -> Leitura/Exibição -> Retorno.', 1, '2026-09-28 10:47:37', NULL, NULL),
	(535, 50, 'multipla_escolha', 'Qual é a diferença crucial em C++ entre o operador de atribuição (=) e o operador de comparação de igualdade (==)?', 'Apenas um sinal guarda um valor; o sinal duplo realiza a verificação lógica.', 1, '2026-09-28 10:47:37', NULL, NULL),
	(536, 50, 'completar_lacunas', 'O operador lógico "ou" do Portugol é traduzido para C++ utilizando os dois caracteres _______.', 'Símbolo das duas barras verticais (pipe duplo).', 1, '2026-09-28 10:47:37', NULL, NULL),
	(537, 50, 'ordenar_blocos', 'Ordene os blocos para estruturar uma verificação se um número é positivo, negativo ou zero usando if, else if e else:', 'Siga a lógica encadeada: Teste positivo -> Teste negativo -> Senão (zero).', 1, '2026-09-28 10:47:37', NULL, NULL),
	(538, 50, 'multipla_escolha', 'No comando switch em C++, o que acontece se o comando "break" for omitido ao final de um "case"?', 'Sem o break, a execução não para e continua nos casos seguintes.', 1, '2026-09-28 10:47:37', NULL, NULL),
	(539, 50, 'completar_lacunas', 'A diretiva de pré-processamento para incluir bibliotecas como a <iostream> no início do código C++ é o comando _______.', 'Começa com o caractere cerquilha (#).', 1, '2026-09-28 10:47:37', NULL, NULL),
	(540, 50, 'ordenar_blocos', 'Ordene os blocos para criar um laço for que calcula e exibe a tabuada do número 5 (de 5 x 1 até 5 x 10):', 'Programe o for de 1 a 10 e multiplique o contador por 5 no cout.', 1, '2026-09-28 10:47:37', NULL, NULL),
	(541, 50, 'multipla_escolha', 'Qual é a principal diferença entre os laços "while" e "do-while" em C++?', 'A diferença reside no momento em que a condição lógica é avaliada.', 1, '2026-09-28 10:47:37', NULL, NULL),
	(542, 50, 'completar_lacunas', 'A instrução _______ 0; no final da função main indica ao sistema operacional que o programa encerrou sem erros.', 'Palavra-chave de retorno da função.', 1, '2026-09-28 10:47:37', NULL, NULL),
	(543, 50, 'ordenar_blocos', 'Ordene os blocos para criar um programa C++ completo que lê a idade e informa se a pessoa é maior de idade (idade >= 18):', 'Monte a sequência completa: Inclusão -> main -> Leitura -> Condicional -> Retorno.', 1, '2026-09-28 10:47:37', NULL, NULL),
	(544, 51, 'multipla_escolha', 'Como se declara um vetor de 5 números inteiros chamado "numeros" em C++?', 'No C++, o tipo vem primeiro, seguido do nome e do tamanho entre colchetes.', 1, '2026-09-28 11:05:19', NULL, NULL),
	(545, 51, 'completar_lacunas', 'Diferente do Portugol onde alguns índices podem iniciar em 1, em C++ os índices de um vetor SEMPRE começam no número _______.', 'Informe o primeiro índice numérico de um array em C++.', 1, '2026-09-28 11:05:19', NULL, NULL),
	(546, 51, 'ordenar_blocos', 'Ordene os blocos para declarar um vetor de 5 inteiros, atribuir o valor 10 à sua primeira posição e exibi-lo:', 'Declare o vetor, atribua o valor no índice 0 e faça a impressão com cout.', 1, '2026-09-28 11:05:19', NULL, NULL),
	(547, 51, 'multipla_escolha', 'Em um vetor declarado como int vet[10]; em C++, qual é o índice da ÚLTIMA posição válida?', 'Lembre-se que os índices vão de 0 até (tamanho - 1).', 1, '2026-09-28 11:05:19', NULL, NULL),
	(548, 51, 'completar_lacunas', 'Para acessar o terceiro elemento de um vetor chamado "notas", escrevemos a instrução notas[_______].', 'O terceiro elemento fica no índice 2 (pois a contagem começa em 0).', 1, '2026-09-28 11:05:19', NULL, NULL),
	(549, 51, 'ordenar_blocos', 'Ordene os blocos para criar um laço for que lê 5 números inteiros digitados pelo usuário e os armazena no vetor vet:', 'Monte a estrutura: for (int i = 0; i < 5; i++) { cin >> vet[i]; }', 1, '2026-09-28 11:05:19', NULL, NULL),
	(550, 51, 'ordenar_blocos', 'Ordene os blocos para imprimir todos os elementos de um vetor de 5 posições separados por espaços:', 'Monte o laço for variando de 0 a 4 e exiba vet[i] com um espaço.', 1, '2026-09-28 11:05:19', NULL, NULL),
	(551, 51, 'multipla_escolha', 'O que ocorre em C++ ao tentar acessar a posição vet[5] em um vetor declarado como int vet[5]?', 'A posição 5 está fora dos limites (índices válidos: 0 a 4), gerando comportamento indefinido ou erro de memória.', 1, '2026-09-28 11:05:19', NULL, NULL),
	(552, 51, 'completar_lacunas', 'Podemos inicializar um vetor diretamente na declaração usando chaves, como por exemplo: int valores[3] = {10, 20, _______}; para definir o valor 30 na última posição.', 'Informe o valor numérico que completa o elemento do vetor.', 1, '2026-09-28 11:05:19', NULL, NULL),
	(553, 51, 'ordenar_blocos', 'Ordene os blocos para declarar um vetor de notas, ler a primeira nota no índice 0 e exibi-la no terminal:', 'Siga a sequência: Declaração do vetor -> Leitura com cin -> Exibição com cout.', 1, '2026-09-28 11:05:19', NULL, NULL),
	(554, 52, 'multipla_escolha', 'Ao calcular a soma dos elementos de um vetor em C++, com qual valor a variável acumuladora "soma" deve ser inicializada?', 'O acumulador de soma deve começar com o elemento neutro da adição.', 1, '2026-09-28 11:14:52', NULL, NULL),
	(555, 52, 'completar_lacunas', 'Para encontrar o maior elemento de um vetor, é boa prática inicializar a variável "maior" com o primeiro elemento vet[_______].', 'Informe o índice da primeira posição do vetor.', 1, '2026-09-28 11:14:52', NULL, NULL),
	(556, 52, 'ordenar_blocos', 'Ordene os blocos para calcular a soma de todos os elementos de um vetor de 5 números inteiros:', 'Siga a sequência: Inicialização do acumulador -> Laço for -> Acumulação com +=.', 1, '2026-09-28 11:14:52', NULL, NULL),
	(557, 52, 'multipla_escolha', 'Se temos um vetor de 4 notas e a variável "soma" contém a soma total, como calculamos a média em formato decimal (float) em C++?', 'A média é a divisão da soma pelo número total de elementos em formato de ponto flutuante.', 1, '2026-09-28 11:14:52', NULL, NULL),
	(558, 52, 'completar_lacunas', 'Para contar quantos elementos são pares em um vetor, testamos se o resto da divisão por 2 é igual a zero: if (vet[i] % 2 == _______).', 'Informe o valor numérico que representa o resto de uma divisão por 2 para números pares.', 1, '2026-09-28 11:14:52', NULL, NULL),
	(559, 52, 'ordenar_blocos', 'Ordene os blocos para criar a lógica que descobre o maior valor em um vetor de 5 elementos:', 'Inicialize maior com vet[0], percorra de 1 a 4 e atualize maior se vet[i] for superior.', 1, '2026-09-28 11:14:52', NULL, NULL),
	(560, 52, 'ordenar_blocos', 'Ordene os blocos para contar quantos alunos foram aprovados (nota >= 6) em um vetor de 5 notas:', 'Inicialize o contador -> Percorra com o for -> Verifique com if -> Incremente o contador.', 1, '2026-09-28 11:14:52', NULL, NULL),
	(561, 52, 'multipla_escolha', 'Dado o vetor int v[4] = {3, 8, 2, 10};, qual é o resultado da expressão v[1] + v[3]?', 'Lembre-se: v[1] é o segundo elemento (8) e v[3] é o quarto elemento (10).', 1, '2026-09-28 11:14:52', NULL, NULL),
	(562, 52, 'completar_lacunas', 'Para realizar uma busca simples em um vetor para encontrar um valor específico, usamos o operador de igualdade: if (vet[i] _______ valorProcurado).', 'Operador de comparação de igualdade em C++.', 1, '2026-09-28 11:14:52', NULL, NULL),
	(563, 52, 'ordenar_blocos', 'Ordene os blocos para copiar todos os elementos do vetor A para o vetor B:', 'Utilize um laço for atribuindo B[i] = A[i] a cada iteração.', 1, '2026-09-28 11:14:52', NULL, NULL),
	(564, 53, 'multipla_escolha', 'Como declaramos uma matriz de inteiros chamada "mat" com 3 linhas e 4 colunas em C++?', 'No C++, a primeira dimensão é a linha e a segunda é a coluna, cada uma entre colchetes separados.', 1, '2026-09-28 11:14:52', NULL, NULL),
	(565, 53, 'completar_lacunas', 'Para acessar o elemento situado na primeira linha e segunda coluna de uma matriz mat, escrevemos mat[0][_______].', 'Índice da segunda coluna (lembrando que a contagem começa em 0).', 1, '2026-09-28 11:14:52', NULL, NULL),
	(566, 53, 'ordenar_blocos', 'Ordene os blocos para declarar e inicializar uma matriz 2x2 com valores numéricos em C++:', 'Siga a sintaxe: tipo nome[linhas][colunas] = {{...}, {...}};', 1, '2026-09-28 11:14:52', NULL, NULL),
	(567, 53, 'multipla_escolha', 'Quantos elementos no total possui uma matriz declarada como float m[3][5] em C++?', 'Multiplique a quantidade de linhas pelo número de colunas.', 1, '2026-09-28 11:14:52', NULL, NULL),
	(568, 53, 'completar_lacunas', 'Para percorrer todos os elementos de uma matriz bidimensional, utilizamos dois laços for _______.', 'Termo usado para laços colocados um dentro do outro.', 1, '2026-09-28 11:14:52', NULL, NULL),
	(569, 53, 'ordenar_blocos', 'Ordene os blocos para estruturar a leitura de uma matriz 2x3 pelo teclado usando dois laços for:', 'O laço externo controla as linhas (i) e o laço interno controla as colunas (j).', 1, '2026-09-28 11:14:52', NULL, NULL),
	(570, 53, 'ordenar_blocos', 'Ordene os blocos para imprimir uma matriz 2x3 em formato de grade, inserindo uma quebra de linha ao término de cada linha da matriz:', 'Após imprimir todos os elementos de uma linha com o laço interno, execute cout << endl;', 1, '2026-09-28 11:14:52', NULL, NULL),
	(571, 53, 'multipla_escolha', 'Em uma instrução de acesso a elemento mat[i][j], o que representam os índices i e j, respectivamente?', 'Siga a convenção universal de matrizes: linha primeiro, coluna depois.', 1, '2026-09-28 11:14:52', NULL, NULL),
	(572, 53, 'completar_lacunas', 'A posição mat[1][2] se refere à segunda linha e _______ coluna da matriz.', 'Ordinal correspondente ao índice de coluna 2.', 1, '2026-09-28 11:14:52', NULL, NULL),
	(573, 53, 'ordenar_blocos', 'Ordene os blocos para atribuir o valor zero a todas as posições de uma matriz 3x3:', 'Aninhe os laços i e j e execute a atribuição mat[i][j] = 0;', 1, '2026-09-28 11:14:52', NULL, NULL),
	(574, 54, 'multipla_escolha', 'Qual é a classe de dados padrão em C++ utilizada para manipular cadeias de caracteres (textos)?', 'Em C++, utilizamos o tipo string para representar textos de forma dinâmica.', 1, '2026-09-28 11:16:03', NULL, NULL),
	(575, 54, 'completar_lacunas', 'Para ler uma linha completa de texto contendo espaços digitada pelo usuário, usamos a função getline(cin, _______).', 'Informe o nome da variável do tipo string que receberá o texto digitado.', 1, '2026-09-28 11:16:03', NULL, NULL),
	(576, 54, 'ordenar_blocos', 'Ordene os blocos para declarar uma string, ler o nome completo do usuário com espaço e exibi-lo:', 'Declare a string -> Utilize getline(cin, nome) -> Exiba com cout.', 1, '2026-09-28 11:16:03', NULL, NULL),
	(577, 54, 'multipla_escolha', 'Dada a variável string texto = "C++";, qual método retorna a quantidade de caracteres contida nessa string?', 'O método .length() (ou .size()) retorna o número de caracteres de uma string.', 1, '2026-09-28 11:16:03', NULL, NULL),
	(578, 54, 'completar_lacunas', 'Para obter o primeiro caractere de uma variável string chamada "palavra", acessamos a posição palavra[_______].', 'Assim como nos vetores, os caracteres de uma string começam no índice 0.', 1, '2026-09-28 11:16:03', NULL, NULL),
	(579, 54, 'ordenar_blocos', 'Ordene os blocos para concatenar duas strings (nome e sobrenome) com um espaço entre elas:', 'Crie a string completa juntando nome + " " + sobrenome.', 1, '2026-09-28 11:16:03', NULL, NULL),
	(580, 54, 'ordenar_blocos', 'Ordene os blocos para criar um laço for que percorre e imprime cada caractere de uma string palavra:', 'O laço deve ir de i = 0 até i < palavra.length().', 1, '2026-09-28 11:16:03', NULL, NULL),
	(581, 54, 'multipla_escolha', 'O que faz o operador "+" quando aplicado entre duas variáveis do tipo string em C++?', 'O operador + une (concatena) duas strings em uma só.', 1, '2026-09-28 11:16:03', NULL, NULL),
	(582, 54, 'completar_lacunas', 'Para garantir o suporte completo a manipulação de strings em C++, devemos incluir a biblioteca #include <_______>.', 'Nome do cabeçalho da biblioteca de textos em C++.', 1, '2026-09-28 11:16:03', NULL, NULL),
	(583, 54, 'ordenar_blocos', 'Ordene os blocos para verificar se duas strings s1 e s2 são idênticas usando a estrutura condicional if:', 'Compare diretamente as duas variáveis com o operador de igualdade ==.', 1, '2026-09-28 11:16:03', NULL, NULL),
	(584, 55, 'multipla_escolha', 'Qual palavra-chave é utilizada em C++ para definir o tipo de retorno de um procedimento que NÃO devolve nenhum valor?', 'Funções sem retorno utilizam o tipo void.', 1, '2026-09-28 11:16:03', NULL, NULL),
	(585, 55, 'completar_lacunas', 'Para encerrar a execução de uma função e enviar o valor calculado de volta ao chamador, usamos a instrução _______.', 'Comando responsável por retornar o valor de uma função.', 1, '2026-09-28 11:16:03', NULL, NULL),
	(586, 55, 'ordenar_blocos', 'Ordene os blocos para criar uma função chamada "soma" que recebe dois inteiros e retorna a soma deles:', 'Cabeçalho com int soma(int a, int b) -> Bloco de retorno.', 1, '2026-09-28 11:16:03', NULL, NULL),
	(587, 55, 'multipla_escolha', 'Onde uma função deve ser declarada em C++ para poder ser chamada diretamente dentro da função main() sem protótipos prévios?', 'Funções declaradas antes da main() já são reconhecidas diretamente pelo compilador.', 1, '2026-09-28 11:16:03', NULL, NULL),
	(588, 55, 'completar_lacunas', 'Ao declarar uma função que calcula o dobro de um número do tipo float, o tipo de retorno especificado no cabeçalho deve ser _______.', 'Se o resultado é decimal, o tipo de retorno deve ser float.', 1, '2026-09-28 11:16:03', NULL, NULL),
	(589, 55, 'ordenar_blocos', 'Ordene os blocos para criar um procedimento void que exibe uma mensagem de boas-vindas:', 'Defina void exibirMensagem() e faça a impressão com cout.', 1, '2026-09-28 11:16:03', NULL, NULL),
	(590, 55, 'ordenar_blocos', 'Ordene os blocos para chamar a função somar(5, 3) dentro do main e armazenar o resultado na variável res:', 'Declare res -> Atribua o retorno da chamada -> Exiba res.', 1, '2026-09-28 11:16:03', NULL, NULL),
	(591, 55, 'multipla_escolha', 'Na passagem de parâmetros por VALOR em C++, o que acontece com a variável original que foi passada como argumento?', 'Na passagem por valor é criada uma cópia local, mantendo a variável original inalterada.', 1, '2026-09-28 11:16:03', NULL, NULL),
	(592, 55, 'completar_lacunas', 'Quando uma função necessita de múltiplos parâmetros, eles devem ser separados por _______ na sua declaração.', 'Caractere de separação entre parâmetros em funções C++.', 1, '2026-09-28 11:16:03', NULL, NULL),
	(593, 55, 'ordenar_blocos', 'Ordene os blocos para criar uma função bool chamada ehPar que retorna true se um número for par:', 'Verifique n % 2 == 0 e retorne true ou false.', 1, '2026-09-28 11:16:03', NULL, NULL),
	(594, 56, 'multipla_escolha', 'Qual símbolo é utilizado na declaração de um parâmetro de função para indicar que ele deve ser passado por REFERÊNCIA em C++?', 'O operador & (e comercial) indica passagem por referência.', 1, '2026-09-28 11:17:39', NULL, NULL),
	(595, 56, 'completar_lacunas', 'Quando alteramos o valor de um parâmetro passado por referência dentro de uma função, a variável _______ declarada no main também tem seu valor alterado.', 'Informe o termo que define a variável passada na chamada da função.', 1, '2026-09-28 11:17:39', NULL, NULL),
	(596, 56, 'ordenar_blocos', 'Ordene os blocos para criar uma função "trocar" que permuta os valores de duas variáveis inteiras por referência:', 'Declare void trocar(int &a, int &b) e use uma variável aux para realizar a troca.', 1, '2026-09-28 11:17:39', NULL, NULL),
	(597, 56, 'multipla_escolha', 'Por padrão, como os vetores (arrays) são passados para funções em C++?', 'Os vetores em C++ são passados sempre por referência (endereço de memória do primeiro elemento).', 1, '2026-09-28 11:17:39', NULL, NULL),
	(598, 56, 'completar_lacunas', 'Para definir uma função que altera diretamente a variável inteira "x", declaramos o parâmetro como: void dobrar(int _______x).', 'Operador de referência em C++.', 1, '2026-09-28 11:17:39', NULL, NULL),
	(599, 56, 'ordenar_blocos', 'Ordene os blocos para criar a função "dobrar" que multiplica por 2 o valor do parâmetro passado por referência:', 'Crie o cabeçalho void dobrar(int &num) e aplique num *= 2;', 1, '2026-09-28 11:17:39', NULL, NULL),
	(600, 56, 'ordenar_blocos', 'Ordene os blocos para criar uma função que recebe um vetor de inteiros e seu tamanho, zerando todas as suas posições:', 'Receba v[] e tam no parâmetro, e use um for de 0 até tam para zerar v[i].', 1, '2026-09-28 11:17:39', NULL, NULL),
	(601, 56, 'multipla_escolha', 'Qual é a principal vantagem de passar grandes estruturas de dados por referência para funções?', 'Evita a cópia inteira dos dados na memória, melhorando a velocidade e economizando RAM.', 1, '2026-09-28 11:17:39', NULL, NULL),
	(602, 56, 'completar_lacunas', 'Para passar um parâmetro por referência evitando que a função altere seu valor original, utilizamos a palavra-chave _______ antes do tipo.', 'Palavra-chave para garantir que o parâmetro seja somente leitura.', 1, '2026-09-28 11:17:39', NULL, NULL),
	(603, 56, 'ordenar_blocos', 'Ordene os blocos para declarar uma variável n=5, passar por referência para a função dobrar(n) e exibir o valor atualizado de n:', 'Declare n = 5 -> Chame dobrar(n) -> Imprima n.', 1, '2026-09-28 11:17:39', NULL, NULL),
	(604, 57, 'multipla_escolha', 'Qual palavra-chave é utilizada em C++ para definir um registro/estrutura personalizada com diferentes tipos de dados?', 'Utilize a palavra-chave struct para definir estruturas.', 1, '2026-09-28 11:17:39', NULL, NULL),
	(605, 57, 'completar_lacunas', 'Para acessar ou atribuir um valor ao membro de uma struct, utilizamos o operador de _______ (ponto).', 'Informe o nome do caractere/símbolo utilizado para acessar membros de uma struct.', 1, '2026-09-28 11:17:39', NULL, NULL),
	(606, 57, 'ordenar_blocos', 'Ordene os blocos para definir uma struct chamada Pessoa contendo nome (string) e idade (int):', 'Siga o padrão: struct Pessoa { string nome; int idade; };', 1, '2026-09-28 11:17:39', NULL, NULL),
	(607, 57, 'multipla_escolha', 'Qual sinal obrigatório deve ser colocado logo após o fechamento de chaves } na definição de uma struct em C++?', 'Toda definição de struct deve ser finalizada com ponto e vírgula ;', 1, '2026-09-28 11:17:39', NULL, NULL),
	(608, 57, 'completar_lacunas', 'Ao declararmos Aluno turma[30]; em C++, a variável turma é considerada um _______ de structs.', 'Estrutura unidimensional que armazena múltiplos elementos do tipo Aluno.', 1, '2026-09-28 11:17:39', NULL, NULL),
	(609, 57, 'ordenar_blocos', 'Ordene os blocos para declarar uma variável p1 do tipo struct Pessoa, atribuindo "Carlos" ao nome e 25 à idade:', 'Declare Pessoa p1; -> Defina p1.nome -> Defina p1.idade.', 1, '2026-09-28 11:17:39', NULL, NULL),
	(610, 57, 'ordenar_blocos', 'Ordene os blocos para ler via teclado a nota de um aluno armazenada dentro do campo a1.nota:', 'Exiba prompt -> Leia cin >> a1.nota;', 1, '2026-09-28 11:17:39', NULL, NULL),
	(611, 57, 'multipla_escolha', 'Dada a definição: struct Carro { string marca; int ano; }; Carro c1;, qual instrução define o ano de c1 como 2024?', 'Utilize a variável seguida do ponto e do nome do campo: c1.ano = 2024;', 1, '2026-09-28 11:17:39', NULL, NULL),
	(612, 57, 'completar_lacunas', 'Para acessar o campo "idade" da pessoa na segunda posição do vetor pessoas[5], escrevemos: pessoas[1]._______ .', 'Nome do membro/campo da struct que armazena a idade.', 1, '2026-09-28 11:17:39', NULL, NULL),
	(613, 57, 'ordenar_blocos', 'Ordene os blocos para criar um vetor de 2 alunos e exibir o nome do primeiro aluno (turma[0].nome):', 'Declare Aluno turma[2]; -> Atribua o nome no índice 0 -> Imprima turma[0].nome.', 1, '2026-09-28 11:17:39', NULL, NULL),
	(614, 58, 'multipla_escolha', 'Como passamos uma variável do tipo struct para uma função em C++?', 'A struct é passada como parâmetro informando seu tipo e nome no cabeçalho da função.', 1, '2026-09-28 11:19:40', NULL, NULL),
	(615, 58, 'completar_lacunas', 'Para ler o preço dentro de um vetor de structs chamado "produtos" no índice "i", escrevemos produtos[i]._______ .', 'Informe o nome do membro/campo que representa o preço.', 1, '2026-09-28 11:19:40', NULL, NULL),
	(616, 58, 'ordenar_blocos', 'Ordene os blocos para criar uma função void que exibe os dados de uma struct Pessoa recebida por referência constante:', 'Defina void exibir(const Pessoa &p) e faça a impressão dos campos com cout.', 1, '2026-09-28 11:19:40', NULL, NULL),
	(617, 58, 'multipla_escolha', 'Qual é a principal vantagem de passar uma struct para uma função utilizando referência constante (const StructName &s)?', 'Evita a cópia completa da estrutura na memória e previne alterações acidentais.', 1, '2026-09-28 11:19:40', NULL, NULL),
	(618, 58, 'completar_lacunas', 'Para permitir que uma função altere os dados de um elemento de um vetor de structs, a passagem do parâmetro deve ser feita por _______.', 'Termo usado para passagem que permite modificação da variável original.', 1, '2026-09-28 11:19:40', NULL, NULL),
	(619, 58, 'ordenar_blocos', 'Ordene os blocos para calcular a média de preços de um vetor de 5 produtos:', 'Inicialize a soma, percorra o vetor somando prods[i].preco e divida por 5.', 1, '2026-09-28 11:19:40', NULL, NULL),
	(620, 58, 'ordenar_blocos', 'Ordene os blocos para buscar um produto pelo nome dentro de um vetor de structs de 5 posições:', 'Percorra com o laço for, compare prods[i].nome com a busca e exiba a mensagem.', 1, '2026-09-28 11:19:40', NULL, NULL),
	(621, 58, 'multipla_escolha', 'Em um vetor Aluno turma[10];, qual é a sintaxe correta para acessar a nota do terceiro aluno?', 'O terceiro aluno está no índice 2: turma[2].nota.', 1, '2026-09-28 11:19:40', NULL, NULL),
	(622, 58, 'completar_lacunas', 'Um vetor de structs agrupa múltiplos registros do mesmo tipo acessíveis através de um índice _______.', 'Tipo de dado que identifica a posição de um elemento no vetor.', 1, '2026-09-28 11:19:40', NULL, NULL),
	(623, 58, 'ordenar_blocos', 'Ordene os blocos para declarar uma struct Item, criar um vetor de 2 itens e definir o nome do primeiro item:', 'Declare a struct -> Crie o vetor -> Atribua valor ao campo do elemento no índice 0.', 1, '2026-09-28 11:19:40', NULL, NULL),
	(624, 59, 'multipla_escolha', 'O que caracteriza uma variável com escopo LOCAL em C++?', 'Variáveis locais são acessíveis apenas dentro do bloco ou função onde foram declaradas.', 1, '2026-09-28 11:19:40', NULL, NULL),
	(625, 59, 'completar_lacunas', 'Variáveis declaradas fora de qualquer função possuem escopo _______ e podem ser acessadas por qualquer parte do programa.', 'Informe o termo referente ao escopo acessível por todo o código.', 1, '2026-09-28 11:19:40', NULL, NULL),
	(626, 59, 'ordenar_blocos', 'Ordene os blocos para declarar uma constante global TAMANHO = 10 e utilizá-la para percorrer um vetor em uma função:', 'Declare const int TAMANHO = 10 fora -> Crie a função usando TAMANHO no laço.', 1, '2026-09-28 11:19:40', NULL, NULL),
	(627, 59, 'multipla_escolha', 'Qual palavra-chave é utilizada em C++ para declarar um valor constante que não pode ser alterado durante a execução?', 'A palavra-chave const torna o valor imutável.', 1, '2026-09-28 11:19:40', NULL, NULL),
	(628, 59, 'completar_lacunas', 'Em C++, uma variável local só existe e permanece válida dentro do bloco de código delimitado por _______.', 'Nome do caractere delimitador { } de blocos em C++.', 1, '2026-09-28 11:19:40', NULL, NULL),
	(629, 59, 'ordenar_blocos', 'Ordene os blocos para demonstrar o sombreamento de variável local em relação a uma variável global com mesmo nome:', 'Declare x global -> No main declare x local -> Exiba o x local com cout.', 1, '2026-09-28 11:19:40', NULL, NULL),
	(630, 59, 'ordenar_blocos', 'Ordene os blocos para criar uma função que recebe um parâmetro constante e exibe seu valor sem permitir alteração:', 'Defina void imprimir(const int num) e faça a exibição com cout.', 1, '2026-09-28 11:19:40', NULL, NULL),
	(631, 59, 'multipla_escolha', 'O que acontece ao tentar modificar o valor de uma variável declarada com o modificador const?', 'O compilador gera um erro informando que a variável é somente leitura.', 1, '2026-09-28 11:19:40', NULL, NULL),
	(632, 59, 'completar_lacunas', 'Constantes globais escritas em letras maiúsculas por convenção são precedidas pela palavra-chave _______.', 'Informe a palavra-chave de constante em C++.', 1, '2026-09-28 11:19:40', NULL, NULL),
	(633, 59, 'ordenar_blocos', 'Ordene os blocos para estruturar adequadamente um programa em C++ com bibliotecas, constante e função main:', 'Includes -> Namespace -> Constantes globais -> Função main.', 1, '2026-09-28 11:19:40', NULL, NULL),
	(634, 60, 'multipla_escolha', 'Qual estrutura de controle é mais recomendada para criar o laço principal de um menu interativo com opções de usuário (ex: 1-Cadastrar, 2-Listar, 0-Sair)?', 'A estrutura do-while garante que o menu seja exibido ao menos uma vez antes da checagem de saída.', 1, '2026-09-28 12:03:10', NULL, NULL),
	(635, 60, 'completar_lacunas', 'Para controlar a quantidade real de elementos armazenados em um vetor de structs de tamanho fixo, utilizamos uma variável inteira que atua como _______ de registros.', 'Variável responsável por armazenar a quantidade atual de itens cadastrados.', 1, '2026-09-28 12:03:10', NULL, NULL),
	(636, 60, 'ordenar_blocos', 'Ordene os blocos para criar a estrutura principal do menu do programa com a instrução do-while:', 'Monte a estrutura do { ... } while (opcao != 0);.', 1, '2026-09-28 12:03:10', NULL, NULL),
	(637, 60, 'multipla_escolha', 'Por que a variável contador de cadastros (ex: int &total) deve ser passada por REFERÊNCIA para a função de inserção?', 'Para que o incremento do contador feito na função persista na variável original do main().', 1, '2026-09-28 12:03:10', NULL, NULL),
	(638, 60, 'completar_lacunas', 'Durante a busca de um registro por nome em um vetor de structs, caso o item seja encontrado, utilizamos a instrução _______ para interromper a busca imediatamente.', 'Comando que encerra a execução de um laço de repetição.', 1, '2026-09-28 12:03:10', NULL, NULL),
	(639, 60, 'ordenar_blocos', 'Ordene os blocos da função cadastrarAluno que recebe o vetor, lê os dados no índice atual e incrementa o contador:', 'Receba o vetor e &qtd -> Leia o dado em v[qtd] -> Incremente qtd++.', 1, '2026-09-28 12:03:10', NULL, NULL),
	(640, 60, 'ordenar_blocos', 'Ordene os blocos da função listarAlunos para percorrer e exibir todos os registros cadastrados até o momento:', 'Use const no parâmetro para leitura -> Percorra de 0 até qtd -> Exiba os campos do vetor.', 1, '2026-09-28 12:03:10', NULL, NULL),
	(641, 60, 'multipla_escolha', 'O que acontece ao tentar cadastrar um novo elemento sem verificar previamente se o contador atingiu o tamanho máximo do vetor?', 'Acessar índices fora dos limites do vetor gera comportamento indefinido ou erro de memória.', 1, '2026-09-28 12:03:10', NULL, NULL),
	(642, 60, 'completar_lacunas', 'Antes de realizar uma nova inserção em um vetor de capacidade MAX, devemos testar se o contador atual de itens é _______ que MAX.', 'Operador de comparação lógica indicando que ainda há espaço disponível.', 1, '2026-09-28 12:03:10', NULL, NULL),
	(643, 60, 'ordenar_blocos', 'Ordene os blocos da função main() configurando as variáveis iniciais e invocando a execução do menu:', 'Declare o vetor e contador -> Inicie o do-while -> Chame as funções de acordo com a escolha.', 1, '2026-09-28 12:03:10', NULL, NULL);
