INSERT INTO `linguagens` (`id_linguagem`, `nome_linguagem`, `descricao`, `nivel`, `img`, `id_admin_criador`, `data_criacao`, `id_admin_editor`, `data_atualizacao`) VALUES
	(1, 'Lógica de Programação', 'Base fundamental de raciocínio lógico e pensamento computacional antes da sintaxe textual.', 'Iniciante', '', 1, '2026-08-26 10:33:34', NULL, NULL);
INSERT INTO `modulos` (`id_modulo`, `id_linguagem`, `titulo_modulo`, `descricao_modulo`, `ordem_modulo`, `id_admin_criador`, `data_criacao`, `id_admin_editor`, `data_atualizacao`) VALUES
	(1, 1, 'Introdução ao Pensamento Computacional', 'Desenvolvimento dos pilares de decomposição, reconhecimento de padrões, abstração e algoritmos.', 1, 1, '2026-08-26 10:34:01', NULL, NULL),
	(2, 1, 'Introdução ao Pseudocódigo e Algoritmos Estruturados', 'Transição do pensamento computacional abstrato para a escrita de algoritmos estruturados em pseudocódigo.', 2, 1, NULL, NULL, NULL),
	(3, 1, 'Laços de Repetição e Estruturas de Dados Simples', 'Aprofundamento prático em estruturas de repetição (Enquanto, Para, Faca-Enquanto) e introdução a vetores e modularização.', 3, 1, '2026-09-24 19:41:52', NULL, NULL),
	(4, 1, 'Algoritmos Avançados, Manipulação de Dados e Práticas do Mundo Real', 'Aprofundamento em algoritmos de ordenação, busca avançada, registros/estruturas de dados personalizadas, recursividade e boas práticas de depuração.', 4, 1, '2026-09-24 20:48:59', NULL, NULL),
	(5, 1, 'Introdução à Linguagem C++ (Sintaxe e Fundamentos)', 'Transição prática dos conceitos aprendidos em Portugol para a linguagem C++, cobrindo estrutura básica, biblioteca iostream, tipos de dados, variáveis e operadores.', 5, 1, '2026-09-28 10:32:15', NULL, NULL),
	(6, 1, 'Vetores, Matrizes, Funções e Estruturas em C++ (Conclusão Iniciante)', 'Conclusão da transição de Portugol para C++. Cobertura completa de arranjos unidimensionais (vetores), bidimensionais (matrizes), manipulação de strings, funções e procedimentos, passagem por valor e referência, structs (registros) e projeto integrador final.', 6, 1, '2026-09-28 11:05:19', NULL, NULL);
